window.FAQ=(window.FAQ||[]).concat([
 {id:'hwx-001',thema:'hypotheek-nhg-woning',vraag:'Waar vind je de geldende regels voor NHG en hoe vaak wijzigen die?',antwoord:`De regels staan in de Voorwaarden & Normen van NHG. Deze worden periodiek aangepast, meestal per 1 januari en soms tussentijds. Toets altijd aan de versie die geldt op de datum van de aanvraag. Leg in het dossier vast welke versie je hebt gebruikt.`,tags:['nhg','voorwaarden en normen','dossier'],bron:'NHG'},
 {id:'hwx-002',thema:'hypotheek-nhg-woning',vraag:'Welke versie van de NHG-normen geldt als de offerte voor een wijziging is aangevraagd?',antwoord:`Bepalend is in de regel de datum van de aanvraag of het uitbrengen van de offerte, zoals beschreven in de Voorwaarden & Normen. Een wijziging van de normen kan dus gevolgen hebben voor lopende dossiers. Controleer de overgangsbepalingen in de actuele versie. Leg de datum van aanvraag aantoonbaar vast.`,tags:['nhg','overgangsrecht','offerte'],bron:'NHG'},
 {id:'hwx-003',thema:'hypotheek-nhg-woning',vraag:'Kan een klant NHG krijgen voor een woning die hij niet zelf gaat bewonen?',antwoord:`Nee. NHG is bedoeld voor een woning die de aanvrager zelf als hoofdverblijf gaat bewonen. Verhuur, een tweede woning of een recreatiewoning vallen er niet onder. Leg de bewoningsintentie vast in het dossier.`,tags:['nhg','eigen bewoning','hoofdverblijf'],bron:'NHG'},
 {id:'hwx-004',thema:'hypotheek-nhg-woning',vraag:'Telt een woning met praktijkruimte aan huis mee voor NHG?',antwoord:`Een woning met een beperkt bedrijfsmatig gebruik kan onder voorwaarden in aanmerking komen. De woonfunctie moet daarbij overheersen. Alleen het woongedeelte telt mee voor de lening onder NHG. Controleer de actuele Voorwaarden & Normen en laat de taxateur de verdeling vastleggen.`,tags:['nhg','praktijkruimte','gemengd gebruik'],bron:'NHG'},
 {id:'hwx-005',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er met NHG als de klant later toch gaat verhuren zonder toestemming?',antwoord:`Verhuur zonder toestemming van de geldverstrekker is in strijd met de hypotheekvoorwaarden. Bij een latere restschuld kan NHG dit aanmerken als verwijtbaar handelen. Dan kan de borgstelling geheel of deels vervallen. Wijs de klant hierop en leg dat vast in het adviesrapport.`,tags:['nhg','verhuur','verwijtbaarheid'],bron:'NHG'},
 {id:'hwx-006',thema:'hypotheek-nhg-woning',vraag:'Hoe beoordeelt NHG verwijtbaarheid bij een restschuld?',antwoord:`NHG kijkt of de klant naar redelijkheid heeft bijgedragen aan het ontstaan of het vergroten van het verlies. Voorbeelden zijn het niet melden van betalingsproblemen, onvoldoende meewerken aan verkoop of onjuiste informatie bij de aanvraag. Bij verwijtbaarheid kan de geldverstrekker de restschuld op de klant blijven verhalen. Leg tijdig meewerken en communicatie vast.`,tags:['nhg','restschuld','verwijtbaarheid'],bron:'NHG'},
 {id:'hwx-007',thema:'hypotheek-nhg-woning',vraag:'Welke rol speelt de adviseur bij een klant met NHG en dreigende betalingsachterstand?',antwoord:`Adviseer de klant om direct contact op te nemen met de geldverstrekker. Wijs op de mogelijkheden binnen NHG, zoals de woonlastenfaciliteit en begeleiding bij verkoop. Vroeg melden vergroot de kans op een oplossing zonder verlies. Leg je adviezen en de datum van contact vast.`,tags:['nhg','betalingsachterstand','nazorg'],bron:'NHG'},
 {id:'hwx-008',thema:'hypotheek-nhg-woning',vraag:'Kan NHG bij een woning met een bouwdepot voor energiebesparende maatregelen?',antwoord:`Ja. NHG kent bij energiebesparende voorzieningen een ruimere NHG-grens dan bij een gewone aankoop. De hoogte en de voorwaarden staan in de actuele Voorwaarden & Normen. Het bedrag voor de maatregelen gaat dan in een bouwdepot. Leg de maatregelen en offertes vast.`,tags:['nhg','NHG-grens','kostengrens','energiebesparing'],bron:'NHG'},
 {id:'hwx-009',thema:'hypotheek-nhg-woning',vraag:'Wat is het risico van het opgeven van NHG bij oversluiten?',antwoord:`Zonder NHG vervalt de bescherming bij een restschuld na gedwongen verkoop. De klant kan ook een hogere rente-opslag krijgen als de LTV hoog is. Een tijdelijke renteverbetering weegt niet altijd op tegen dat risico. Leg deze afweging expliciet vast in het dossier.`,tags:['nhg','oversluiten','afweging'],bron:''},
 {id:'hwx-010',thema:'hypotheek-nhg-woning',vraag:'Kan NHG worden toegevoegd aan een bestaande hypotheek zonder NHG?',antwoord:`Dat kan alleen bij een nieuwe aanvraag waarbij volledig aan de geldende normen wordt getoetst, bijvoorbeeld bij oversluiten of verhogen. Een bestaande lening kan niet achteraf eenvoudig onder NHG worden gebracht. De hele lening moet dan binnen de normen en de NHG-grens passen. Controleer de voorwaarden van de geldverstrekker.`,tags:['nhg','bestaande hypotheek','verhogen'],bron:'NHG'},
 {id:'hwx-011',thema:'hypotheek-nhg-woning',vraag:'Wat als koopsom plus verbouwing net boven de NHG-grens uitkomt?',antwoord:`De NHG-grens geldt voor de totale kosten van de woning, niet alleen voor de lening. Liggen de kosten erboven, dan is NHG in de regel niet mogelijk, ook niet als de klant het meerdere zelf betaalt. Voor energiebesparende voorzieningen kent NHG een ruimere grens. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','NHG-grens','kostengrens','verbouwing'],bron:'NHG'},
 {id:'hwx-012',thema:'hypotheek-nhg-woning',vraag:'Mag de klant met NHG een overbruggingskrediet afsluiten?',antwoord:`Ja, een overbruggingskrediet is binnen NHG mogelijk onder voorwaarden. De overwaarde van de oude woning moet aantoonbaar zijn, bijvoorbeeld met een taxatie of verkoopovereenkomst. De dubbele lasten moeten passen in de toets. Controleer de actuele normen en de voorwaarden van de geldverstrekker.`,tags:['nhg','overbrugging','dubbele lasten'],bron:'NHG'},
 {id:'hwx-013',thema:'hypotheek-nhg-woning',vraag:'Welke stukken bewaar je voor een mogelijke latere claim bij NHG?',antwoord:`Bewaar de aanvraag, de toetsberekening en alle stukken waarop de toets rust. Denk aan inkomensstukken, taxatierapport, koopovereenkomst en bewijs van eigen middelen. Bij een claim kijkt NHG of de lening volgens de normen is verstrekt. Een volledig dossier voorkomt discussie achteraf.`,tags:['nhg','claim','dossier'],bron:'NHG'},
 {id:'hwx-014',thema:'hypotheek-nhg-woning',vraag:'Kan een restschuld van de vorige woning worden meegefinancierd onder NHG?',antwoord:`NHG staat onder voorwaarden toe dat een restschuld van een oude NHG-lening wordt meegefinancierd, als die niet bij NHG is gedeclareerd. Het bindend aanbod moet binnen een jaar na verkoop komen en de restschuld wordt in dezelfde NHG-lening zo snel mogelijk annuïtair of lineair afgelost. Fiscaal is rente op een restschuld alleen onder strikte voorwaarden aftrekbaar. Controleer de actuele Voorwaarden & Normen en leg de fiscale positie vast.`,tags:['nhg','restschuld','meefinancieren'],bron:'NHG'},
 {id:'hwx-015',thema:'hypotheek-nhg-woning',vraag:'Welke kosten mogen onder NHG worden meegefinancierd?',antwoord:`Dat hangt af van de soort transactie en de actuele normen. Bij aankoop gaat het vaak om onder meer koopsom, overdrachtsbelasting, notariskosten, advies, taxatie en borgtochtprovisie, binnen de LTV-grens. Niet elke kostenpost is toegestaan. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','kosten','meefinancieren'],bron:'NHG'},
 {id:'hwx-016',thema:'hypotheek-nhg-woning',vraag:'Valt een consumptief krediet dat wordt afgelost bij aankoop onder NHG?',antwoord:`Het aflossen van een consumptief krediet uit de hypotheek is in de regel niet toegestaan onder NHG. Een lopend krediet telt wel mee als last in de toets. Afhankelijk van de normen kan het krediet vooraf met eigen middelen worden afgelost. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','consumptief krediet','toets'],bron:'NHG'},
 {id:'hwx-017',thema:'hypotheek-nhg-woning',vraag:'Hoe weegt een BKR-registratie mee bij NHG?',antwoord:`NHG stelt eisen aan registraties bij het BKR, met name bij achterstandscoderingen. Een negatieve codering kan tot afwijzing leiden, tenzij de normen een uitzondering kennen. Lopende kredieten tellen mee als last. Vraag het BKR-overzicht vroeg op en leg de beoordeling vast.`,tags:['nhg','bkr','toetsing'],bron:'NHG'},
 {id:'hwx-018',thema:'hypotheek-nhg-woning',vraag:'Welke inkomensdocumenten vraagt NHG minimaal?',antwoord:`De Voorwaarden & Normen beschrijven per inkomenssoort welke stukken nodig zijn. Denk aan een werkgeversverklaring met salarisstrook, een arbeidsmarktscan, een Inkomensbepaling Loondienst of jaarcijfers bij ondernemers. De geldverstrekker kan aanvullende stukken vragen. Leg in het dossier vast welke bron is gebruikt.`,tags:['nhg','inkomen','documenten'],bron:'NHG'},
 {id:'hwx-019',thema:'hypotheek-nhg-woning',vraag:'Kan een zzp-er met korte ondernemingshistorie NHG krijgen?',antwoord:`Dat hangt af van de eisen in de Voorwaarden & Normen voor ondernemers. Vaak is een inkomensverklaring van een erkende rekenexpert nodig. Bij een korte historie kan een prognose een rol spelen, maar dat is niet altijd voldoende. Controleer de actuele normen en de voorwaarden van de geldverstrekker.`,tags:['nhg','zzp','inkomensverklaring'],bron:'NHG'},
 {id:'hwx-020',thema:'hypotheek-nhg-woning',vraag:'Kan NHG als de klant een schenking ontvangt voor de eigen inbreng?',antwoord:`Ja. Een schenking kan als eigen middelen worden ingebracht. Leg vast dat het een schenking is en geen lening, bijvoorbeeld met een schenkingsakte of verklaring. Een lening van familie telt als last mee in de toets.`,tags:['nhg','schenking','eigen middelen'],bron:'NHG'},
 {id:'hwx-021',thema:'hypotheek-nhg-woning',vraag:'Telt een familiebank-lening mee in de NHG-toets?',antwoord:`Ja. Een lening van familie is een financiële verplichting en telt mee in de toets volgens de normen. Ook als de familie afziet van rente of aflossing kan dit relevant zijn. Leg de leningsovereenkomst en de afspraken vast. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','familielening','toets'],bron:'NHG'},
 {id:'hwx-022',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er met NHG bij echtscheiding als één partner de woning overneemt?',antwoord:`De achterblijvende partner kan de hypotheek met NHG overnemen als hij of zij zelfstandig voldoet aan de normen. Er gelden specifieke regels voor het uitkopen van de ex-partner. NHG kent hiervoor soms aanvullende mogelijkheden voor een tijdelijke periode. Controleer de actuele normen en leg de toets op eigen inkomen vast.`,tags:['nhg','echtscheiding','overname'],bron:'NHG'},
 {id:'hwx-023',thema:'hypotheek-nhg-woning',vraag:'Kan een partner uit de hoofdelijke aansprakelijkheid worden ontslagen bij NHG?',antwoord:`Dat beslist de geldverstrekker, niet NHG. De achterblijvende partner moet zelfstandig voldoen aan de normen. Zonder ontslag blijft de vertrekkende partner aansprakelijk voor de schuld. Leg de uitkomst en de gevolgen vast voor beide partners.`,tags:['nhg','hoofdelijkheid','scheiding'],bron:''},
 {id:'hwx-024',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen de NHG-borg en de hypotheekschuld na een paar jaar?',antwoord:`De borg daalt elke maand alsof de lening annuïtair over 30 jaar wordt afgelost. De werkelijke schuld kan hoger zijn, bijvoorbeeld bij een aflossingsvrij deel of extra opname. Het verschil is niet gedekt. Leg uit dat een restschuld boven de borg voor rekening van de klant blijft.`,tags:['nhg','borg','dekking'],bron:'NHG'},
 {id:'hwx-025',thema:'hypotheek-nhg-woning',vraag:'Waarom kan een lineaire lening onder NHG een voordeel hebben ten opzichte van de borg?',antwoord:`Bij een lineaire lening daalt de schuld in het begin sneller dan bij een annuïteit. De dalende borg volgt een annuïtair schema. Daardoor blijft de schuld eerder binnen de borg. Dit heeft geen invloed op de toets of premie, wel op de dekking.`,tags:['nhg','lineair','borg'],bron:'NHG'},
 {id:'hwx-026',thema:'hypotheek-nhg-woning',vraag:'Waarom is een correcte NHG-aanvraag van belang voor de geldverstrekker?',antwoord:`NHG keert bij een verlies alleen uit als de lening volgens de normen is verstrekt. Fouten in de aanvraag kunnen leiden tot een lagere of geen uitkering aan de geldverstrekker. Daarom controleren geldverstrekkers de aanvraag streng. De adviseur levert de basis en moet de stukken zorgvuldig aanleveren.`,tags:['nhg','aanvraag','uitkering'],bron:'NHG'},
 {id:'hwx-027',thema:'hypotheek-nhg-woning',vraag:'Hoe reken je of NHG financieel loont bij een lage LTV?',antwoord:`Vergelijk de eenmalige borgtochtprovisie met het renteverschil over de rentevaste periode. Gebruik de actuele tarieven en de rente-aanbieding van de geldverstrekker. Neem ook de bescherming bij restschuld mee als niet-financieel voordeel. Leg de berekening en de keuze van de klant vast.`,tags:['nhg','rekenvoorbeeld','afweging'],bron:''},
 {id:'hwx-028',thema:'hypotheek-nhg-woning',vraag:'Kan de klant NHG behouden bij een rentemiddeling?',antwoord:`Rentemiddeling bij dezelfde geldverstrekker heeft in de regel geen invloed op de NHG-borgstelling. De lening en het onderpand blijven gelijk. Controleer wel de voorwaarden van de geldverstrekker. Leg de berekening van de rentemiddeling vast.`,tags:['nhg','rentemiddeling','borg'],bron:''},
 {id:'hwx-029',thema:'hypotheek-nhg-woning',vraag:'Mag een klant met NHG extra aflossen?',antwoord:`Ja, extra aflossen is toegestaan binnen de boetevrije ruimte of tegen vergoeding van de geldverstrekker. De NHG-borg daalt volgens een vast schema en niet mee met extra aflossing. Na extra aflossing is de schuld dus beter gedekt. Controleer de voorwaarden van de geldverstrekker.`,tags:['nhg','extra aflossen','borg'],bron:''},
 {id:'hwx-030',thema:'hypotheek-nhg-woning',vraag:'Is een hypotheek met NHG meeneembaar naar een volgende woning?',antwoord:`Sommige geldverstrekkers bieden meeneembaarheid aan. Voor de nieuwe woning wordt opnieuw getoetst of NHG mogelijk is. Er kan opnieuw borgtochtprovisie verschuldigd zijn over het nieuwe bedrag. Controleer de voorwaarden van de geldverstrekker en de actuele normen.`,tags:['nhg','meeneembaarheid','verhuizing'],bron:'NHG'},
 {id:'hwx-031',thema:'hypotheek-nhg-woning',vraag:'Wanneer is een woonlastenfaciliteit niet passend?',antwoord:`De faciliteit is bedoeld voor tijdelijke betalingsproblemen door bijvoorbeeld werkloosheid, arbeidsongeschiktheid of scheiding. Als structureel herstel niet te verwachten is, ligt verkoop meer voor de hand. De geldverstrekker beoordeelt dit volgens de NHG-voorwaarden. Leg de situatie van de klant en het perspectief vast.`,tags:['nhg','woonlastenfaciliteit','betalingsproblemen'],bron:'NHG'},
 {id:'hwx-032',thema:'hypotheek-nhg-woning',vraag:'Kan NHG bij een woning die de klant samen koopt met een niet-partner?',antwoord:`Ja, NHG is mogelijk voor meerdere aanvragers die samen de woning bewonen. Elke aanvrager moet de woning als hoofdverblijf gebruiken. Leg afspraken tussen de kopers vast, bijvoorbeeld in een samenlevingsovereenkomst. Controleer de voorwaarden van de geldverstrekker.`,tags:['nhg','samen kopen','meerdere aanvragers'],bron:'NHG'},
 {id:'hwx-033',thema:'hypotheek-nhg-woning',vraag:'Kan een ouder meetekenen voor een kind dat NHG aanvraagt?',antwoord:`Een ouder die niet in de woning gaat wonen, kan in de regel geen mede-aanvrager zijn onder NHG. Hoofdverblijf is een voorwaarde voor elke aanvrager. Alternatieven zijn een schenking of een onderhandse lening. Controleer de actuele normen.`,tags:['nhg','ouders','meetekenen'],bron:'NHG'},
 {id:'hwx-034',thema:'hypotheek-nhg-woning',vraag:'Wat is het effect van een verlaagde woningwaarde op een lopende NHG-hypotheek?',antwoord:`Een waardedaling heeft geen effect op de borgstelling zolang de klant aan zijn verplichtingen voldoet. Het risico wordt pas relevant bij een verkoop met verlies. Wel kan de geldverstrekker bij een hogere LTV een hogere rente vragen bij renteherziening. Controleer de voorwaarden van de geldverstrekker.`,tags:['nhg','waardedaling','renteherziening'],bron:''},
 {id:'hwx-035',thema:'hypotheek-nhg-woning',vraag:'Moet de klant toestemming vragen aan NHG om de woning onder de schuld te verkopen?',antwoord:`Bij een verwachte restschuld moet de klant vooraf toestemming van de geldverstrekker vragen, die volgens de NHG-regels handelt. Zonder die toestemming loopt de klant risico dat de restschuld niet wordt overgenomen. De verkoopprijs moet marktconform zijn. Leg het traject en de stukken vast.`,tags:['nhg','verkoop met verlies','toestemming'],bron:'NHG'},
 {id:'hwx-036',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er met een restschuld na kwijtschelding door NHG fiscaal?',antwoord:`Fiscaal is kwijtschelding van een schuld onder voorwaarden belast of kan het de aftrek beïnvloeden. Voor de eigen woning gelden specifieke regels. Verwijs de klant voor zijn fiscale positie naar een fiscalist of de Belastingdienst. Leg vast dat je dit hebt gesignaleerd.`,tags:['nhg','kwijtschelding','fiscaal'],bron:'Belastingdienst'},
 {id:'hwx-037',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een NHG-aanvraag bij een woning met achterstallig onderhoud?',antwoord:`De taxateur signaleert het onderhoud en kan herstel als voorwaarde stellen. Herstelkosten kunnen dan onder voorwaarden in een bouwdepot. De marktwaarde na herstel is dan de basis. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','onderhoud','bouwdepot'],bron:'NHG'},
 {id:'hwx-038',thema:'hypotheek-nhg-woning',vraag:'Welke eisen stelt NHG aan het taxatierapport?',antwoord:`NHG vereist een gevalideerd taxatierapport of, in bepaalde gevallen, een toegestane hybride taxatie, beide maximaal 6 maanden oud. De taxateur moet onafhankelijk zijn en aan de kwaliteitseisen voldoen. De WOZ-waarde volstaat niet voor de acceptatie. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','taxatierapport','validatie'],bron:'NHG'},
 {id:'hwx-039',thema:'hypotheek-nhg-woning',vraag:'Is bij een NHG-aanvraag altijd een bouwkundig rapport nodig?',antwoord:`Nee, niet standaard. Een bouwkundig rapport kan nodig zijn als de taxateur of geldverstrekker daar aanleiding voor ziet. Ook bij twijfel over constructie of fundering wordt het gevraagd. Controleer de actuele normen en de voorwaarden van de geldverstrekker.`,tags:['nhg','bouwkundig rapport','keuring'],bron:'NHG'},
 {id:'hwx-040',thema:'hypotheek-nhg-woning',vraag:'Hoe leg je de NHG-toets vast in het dossier?',antwoord:`Bewaar de berekening van de maximale lening, de gebruikte versie van de normen en de onderliggende stukken. Leg vast hoe het inkomen is bepaald en welke lasten zijn meegenomen. Noteer ook welke kosten zijn meegefinancierd. Zo kun je de toets later reconstrueren.`,tags:['nhg','dossier','vastlegging'],bron:'NHG'},
 {id:'hwx-041',thema:'hypotheek-nhg-woning',vraag:'Welke veelgemaakte fouten komen voor bij NHG-aanvragen?',antwoord:`Kosten worden meegefinancierd die niet zijn toegestaan. De NHG-grens wordt verkeerd berekend, bijvoorbeeld zonder verbouwing of verduurzaming. Lopende kredieten of studieschuld worden over het hoofd gezien. Ook ontbreken vaak stukken die de eigen middelen aantonen.`,tags:['nhg','fouten','controle'],bron:'NHG'},
 {id:'hwx-042',thema:'hypotheek-nhg-woning',vraag:'Welke rol speelt een taxatie bij verkoop met verlies onder NHG?',antwoord:`Bij verkoop met verlies moet de verkoopprijs marktconform zijn. Een taxatie onderbouwt de marktwaarde. NHG en de geldverstrekker gebruiken die om te beoordelen of de verkoop verantwoord is. Leg de taxatie en het verkooptraject vast.`,tags:['nhg','verkoop met verlies','taxatie'],bron:'NHG'},
 {id:'hwx-043',thema:'hypotheek-nhg-woning',vraag:'Kan NHG bij een woning in het buitenland?',antwoord:`Nee. NHG geldt alleen voor woningen in Nederland. Een woning in het buitenland valt buiten de regeling. Voor zo een financiering gelden andere voorwaarden.`,tags:['nhg','buitenland','onderpand'],bron:'NHG'},
 {id:'hwx-044',thema:'hypotheek-nhg-woning',vraag:'Kan een woonboot onder NHG worden gefinancierd?',antwoord:`Dat hangt af van de actuele Voorwaarden & Normen en van de vraag of de ligplaats voldoende zeker is. Veel geldverstrekkers financieren woonboten niet of onder strenge voorwaarden. Controleer de actuele normen en de voorwaarden van de geldverstrekker. Leg de status van de ligplaats vast.`,tags:['nhg','woonboot','ligplaats'],bron:'NHG'},
 {id:'hwx-045',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen NHG-borgstelling en een hypotheek met lage LTV?',antwoord:`NHG biedt bescherming bij restschuld na gedwongen verkoop. Een lage LTV verkleint het risico op restschuld, maar geeft geen garantie. De rentekorting bij een lage LTV kan vergelijkbaar zijn met die van NHG. De keuze is een afweging tussen kosten en risico.`,tags:['nhg','ltv','vergelijking'],bron:''},
 {id:'hwx-046',thema:'hypotheek-nhg-woning',vraag:'Kan een klant de borgtochtprovisie terugkrijgen bij vroege aflossing?',antwoord:`Nee. De borgtochtprovisie is eenmalig en wordt in de regel niet terugbetaald bij aflossing of verkoop. Neem dit mee in de afweging als de klant verwacht kort in de woning te blijven. Leg de verwachte woonduur vast.`,tags:['nhg','borgtochtprovisie','aflossing'],bron:'NHG'},
 {id:'hwx-047',thema:'hypotheek-nhg-woning',vraag:'Hoe gaat NHG om met een erfpachtcanon bij de toets?',antwoord:`De canon telt als woonlast mee in de toets, volgens de methode van de leennormen. Een afkoopsom kan onder voorwaarden worden meegefinancierd. De erfpachtvoorwaarden moeten aan de NHG-eisen voldoen. Controleer de actuele Voorwaarden & Normen.`,tags:['nhg','erfpacht','canon'],bron:'NHG'},
 {id:'hwx-048',thema:'hypotheek-nhg-woning',vraag:'Kan NHG worden aangevraagd voor een woning die de klant van familie koopt?',antwoord:`Ja, als de transactie marktconform is en aan de normen voldoet. Een taxatie stelt de marktwaarde vast. Bij een koopsom onder de marktwaarde kan sprake zijn van een schenking. Leg de waarde en de afspraken vast en wijs op de fiscale gevolgen.`,tags:['nhg','familie','onderhandse verkoop'],bron:'NHG'},
 {id:'hwx-049',thema:'hypotheek-nhg-woning',vraag:'Wat moet de adviseur controleren als NHG wordt afgewezen?',antwoord:`Vraag de reden van afwijzing op en toets of die klopt met de normen. Soms is aanvulling van stukken voldoende. Anders kan een financiering zonder NHG mogelijk zijn, met andere voorwaarden. Leg de afwijzing en de alternatieven vast.`,tags:['nhg','afwijzing','alternatieven'],bron:''},
 {id:'hwx-050',thema:'hypotheek-nhg-woning',vraag:'Kan een klant met NHG zijn woning tijdelijk verhuren bij uitzending naar het buitenland?',antwoord:`Tijdelijke verhuur kan in bijzondere situaties met toestemming van de geldverstrekker. De klant moet dit vooraf aanvragen. Ook de fiscale status van de eigen woning kan veranderen. Leg de toestemming en de gevolgen vast.`,tags:['nhg','tijdelijke verhuur','toestemming'],bron:'NHG'},
 {id:'hwx-051',thema:'hypotheek-nhg-woning',vraag:'Wie geeft opdracht tot de taxatie en waarom is dat relevant?',antwoord:`In de regel geeft de klant of de adviseur namens de klant de opdracht via een erkend platform. De taxateur moet onafhankelijk zijn van koper, verkoper en makelaar. Een taxatie in opdracht van de verkoper is meestal niet bruikbaar voor de financiering. Leg vast wie de opdracht gaf.`,tags:['taxatie','opdracht','onafhankelijkheid'],bron:'NWWI'},
 {id:'hwx-052',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een taxatie en een waardebepaling van een makelaar?',antwoord:`Een waardebepaling van een makelaar is een indicatie, vaak voor het bepalen van een vraagprijs. Een taxatierapport voor financiering volgt een vast model en wordt gevalideerd. Geldverstrekkers accepteren een waardebepaling van een makelaar meestal niet als onderbouwing. Leg vast welk document is gebruikt.`,tags:['taxatie','waardebepaling','makelaar'],bron:''},
 {id:'hwx-053',thema:'hypotheek-nhg-woning',vraag:'Mag een taxateur de woning taxeren als hij die ook als makelaar verkoopt?',antwoord:`Nee. Dat is een belangenconflict. Taxateurs moeten onafhankelijk zijn van de transactie. Controleer de onafhankelijkheidsverklaring in het rapport.`,tags:['taxatie','belangenconflict','makelaar'],bron:'NRVT'},
 {id:'hwx-054',thema:'hypotheek-nhg-woning',vraag:'Wat betekent marktwaarde vrij van huur en gebruik?',antwoord:`Dat is de waarde van de woning als die leeg en direct beschikbaar wordt opgeleverd. Bij financiering van een eigen woning is dit de gebruikelijke waarde. Bij verhuurde woningen is de waarde in verhuurde staat vaak lager. Let op welk begrip in het rapport staat.`,tags:['taxatie','marktwaarde','leeg'],bron:''},
 {id:'hwx-055',thema:'hypotheek-nhg-woning',vraag:'Waarom staan er referentiewoningen in een taxatierapport?',antwoord:`De taxateur onderbouwt de marktwaarde met recente verkopen van vergelijkbare woningen. Verschillen in grootte, staat en ligging worden verwerkt. De keuze van referenties bepaalt mede de uitkomst. Kijk als adviseur of de referenties logisch zijn.`,tags:['taxatie','referenties','onderbouwing'],bron:''},
 {id:'hwx-056',thema:'hypotheek-nhg-woning',vraag:'Wat doe je als de referenties in een taxatierapport niet vergelijkbaar lijken?',antwoord:`Vraag de taxateur om een toelichting op de keuze en de correcties. Soms zijn er weinig verkopen in de buurt. Wijzig het rapport niet zelf en vraag niet om een gewenste waarde. Leg de vraag en het antwoord vast.`,tags:['taxatie','referenties','toelichting'],bron:''},
 {id:'hwx-057',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een taxatie die veel hoger is dan de koopsom?',antwoord:`Voor de LTV geldt in de regel de laagste van koopsom en marktwaarde, afhankelijk van de normen en de geldverstrekker. Een hogere taxatie vergroot dus niet zonder meer de leenruimte bij aankoop. Controleer de voorwaarden van de geldverstrekker. Leg de gebruikte waarde vast.`,tags:['taxatie','koopsom','ltv'],bron:'Trhk'},
 {id:'hwx-058',thema:'hypotheek-nhg-woning',vraag:'Mag je een taxatierapport van een andere geldverstrekker hergebruiken?',antwoord:`Een gevalideerd rapport is vaak bruikbaar bij meerdere geldverstrekkers, mits het nog geldig is. Sommige geldverstrekkers stellen eisen aan de opdrachtgever of het model. Controleer de voorwaarden van de geldverstrekker. Vraag zo nodig een heradressering aan.`,tags:['taxatie','hergebruik','geldigheid'],bron:''},
 {id:'hwx-059',thema:'hypotheek-nhg-woning',vraag:'Wat is een heradressering van een taxatierapport?',antwoord:`Daarbij wordt een bestaand rapport op naam van een andere geldverstrekker gezet. Dat kan nodig zijn als de klant van geldverstrekker wisselt. Niet elk platform of elke geldverstrekker accepteert dat. Er kunnen kosten aan verbonden zijn.`,tags:['taxatie','heradressering','wisselen'],bron:''},
 {id:'hwx-060',thema:'hypotheek-nhg-woning',vraag:'Welke onderdelen van een taxatierapport controleer je als adviseur?',antwoord:`Controleer adres, kadastrale gegevens, eigendomssituatie en erfpacht. Kijk naar de marktwaarde, waarde na verbouwing en de genoemde gebreken. Let op opmerkingen over fundering, asbest, bestemming en gebruik. Afwijkingen ten opzichte van de aanvraag bespreek je met de klant.`,tags:['taxatie','controle','rapport'],bron:''},
 {id:'hwx-061',thema:'hypotheek-nhg-woning',vraag:'Wat betekent een opmerking over bestemmingsplan of omgevingsplan in het rapport?',antwoord:`De taxateur toetst of het gebruik past binnen de regels van de gemeente. Een strijdig gebruik, bijvoorbeeld bewoning van een bijgebouw, kan de waarde en financierbaarheid beïnvloeden. Geldverstrekkers kunnen dan afwijzen of voorwaarden stellen. Leg de bevinding en de gevolgen vast.`,tags:['taxatie','omgevingsplan','bestemming'],bron:'Omgevingswet'},
 {id:'hwx-062',thema:'hypotheek-nhg-woning',vraag:'Kan een recreatiewoning als eigen woning worden gefinancierd?',antwoord:`Als permanente bewoning niet is toegestaan, is de woning in de regel niet te financieren als eigen woning. Ook de fiscale eigenwoningregeling kan dan problemen geven. Controleer het omgevingsplan en eventuele persoonsgebonden gedoogbeschikkingen. Leg de status vast in het dossier.`,tags:['recreatiewoning','permanente bewoning','financierbaarheid'],bron:''},
 {id:'hwx-063',thema:'hypotheek-nhg-woning',vraag:'Wat is een kadastraal uittreksel en waarom heb je het nodig?',antwoord:`Het uittreksel toont eigenaar, perceel, oppervlakte en ingeschreven beperkingen zoals erfpacht of hypotheken. Het helpt om te controleren of de verkoper bevoegd is. Ook kun je beperkte rechten en kwalitatieve verplichtingen signaleren. De notaris doet de definitieve controle.`,tags:['kadaster','eigendom','beperkingen'],bron:'Kadaster'},
 {id:'hwx-064',thema:'hypotheek-nhg-woning',vraag:'Wat zijn kwalitatieve verplichtingen en waarom zijn ze relevant?',antwoord:`Dat zijn verplichtingen die met de woning overgaan op de nieuwe eigenaar, zoals onderhoud van een gezamenlijke voorziening. Ze kunnen kosten of beperkingen geven. De taxateur of notaris vermeldt ze. Bespreek ze met de klant als ze de woonlasten raken.`,tags:['kwalitatieve verplichting','notaris','woonlasten'],bron:''},
 {id:'hwx-065',thema:'hypotheek-nhg-woning',vraag:'Wat is een kettingbeding?',antwoord:`Een kettingbeding verplicht de eigenaar een verplichting door te geven aan elke volgende eigenaar. Het kan gaan om bijvoorbeeld een recht van overpad of een bouwbeperking. Het staat in de akte van levering. Signaleer het en bespreek de gevolgen voor gebruik en waarde.`,tags:['kettingbeding','akte','beperking'],bron:''},
 {id:'hwx-066',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een recht van overpad op het perceel?',antwoord:`Een recht van overpad kan het gebruik van de tuin of het erf beperken. Het kan de waarde licht beïnvloeden. De taxateur hoort het te vermelden. Bespreek de praktische gevolgen met de klant.`,tags:['erfdienstbaarheid','overpad','perceel'],bron:''},
 {id:'hwx-067',thema:'hypotheek-nhg-woning',vraag:'Waarom is de oppervlakte volgens NEN 2580 belangrijk?',antwoord:`Taxateurs meten volgens een vaste meetinstructie op basis van NEN 2580. Zo zijn woningen onderling vergelijkbaar. Verschillen met de verkoopbrochure komen vaak voor. Een kleinere oppervlakte kan de taxatiewaarde verlagen.`,tags:['taxatie','oppervlakte','nen 2580'],bron:'NEN'},
 {id:'hwx-068',thema:'hypotheek-nhg-woning',vraag:'Welke gegevens uit het taxatierapport neem je over in de hypotheekaanvraag?',antwoord:`Neem de marktwaarde, de waarde na verbouwing en de bijzonderheden over. Denk ook aan erfpacht, energielabel en eventuele voorwaarden van de taxateur. Controleer of de gegevens overeenkomen met de koopovereenkomst. Verschillen bespreek je voordat de aanvraag wordt ingediend.`,tags:['taxatie','aanvraag','gegevens'],bron:''},
 {id:'hwx-069',thema:'hypotheek-nhg-woning',vraag:'Wanneer kun je bij oversluiten volstaan met de WOZ-waarde?',antwoord:`Sommige geldverstrekkers accepteren de WOZ-waarde bij een lage LTV of bij een verhoging die beperkt is. De WOZ-waarde heeft een oudere peildatum en kan achterlopen. Bij een hoge LTV is een taxatie meestal nodig. Controleer de voorwaarden van de geldverstrekker.`,tags:['woz','oversluiten','waardering'],bron:''},
 {id:'hwx-070',thema:'hypotheek-nhg-woning',vraag:'Wat doe je als de klant de taxatiewaarde betwist?',antwoord:`De klant kan de taxateur om een toelichting vragen. Een second opinion door een andere taxateur is mogelijk, maar geldverstrekkers accepteren niet altijd het hoogste rapport. Shoppen naar een hogere waarde is ongewenst. Leg het verloop vast in het dossier.`,tags:['taxatie','bezwaar','second opinion'],bron:''},
 {id:'hwx-071',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een koper die zonder voorbehoud van financiering wil bieden?',antwoord:`Zonder voorbehoud kan de koper bij een tegenvallende taxatie of afwijzing niet kosteloos ontbinden. Dan kan een boete uit de koopovereenkomst volgen. Breng de financierbaarheid en de waarde vooraf zo goed mogelijk in kaart. Leg vast dat de klant het risico begrijpt.`,tags:['voorbehoud financiering','bieden','risico'],bron:''},
 {id:'hwx-072',thema:'hypotheek-nhg-woning',vraag:'Waarom moet je bij overbieden extra letten op de taxatie?',antwoord:`Bij overbieden kan de koopsom boven de getaxeerde marktwaarde uitkomen. Dan ontstaat een tekort dat de klant met eigen geld moet aanvullen. Bespreek dit voor het bieden. Leg vast dat de klant het risico begrijpt.`,tags:['overbieden','taxatie','eigen geld'],bron:''},
 {id:'hwx-073',thema:'hypotheek-nhg-woning',vraag:'Kan een taxateur een voorwaarde stellen aan de financiering?',antwoord:`De taxateur kan herstel of nader onderzoek adviseren. De geldverstrekker neemt dat over als voorwaarde in de offerte. Bijvoorbeeld een bouwkundige keuring, funderingsonderzoek of herstel van gebreken. Controleer de offerte op zulke voorwaarden.`,tags:['taxatie','voorwaarden','offerte'],bron:''},
 {id:'hwx-074',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met asbest dat in het taxatierapport wordt genoemd?',antwoord:`Asbest is in veel woningen uit een bepaalde bouwperiode aanwezig. De taxateur vermeldt een vermoeden. Bij verwijdering kunnen de kosten hoog zijn. Adviseer nader onderzoek bij geplande verbouwing en leg de bespreking vast.`,tags:['asbest','taxatie','verbouwing'],bron:''},
 {id:'hwx-075',thema:'hypotheek-nhg-woning',vraag:'Wat is een gevolg van een woning op verontreinigde grond?',antwoord:`Bodemverontreiniging kan de waarde en de financierbaarheid beïnvloeden. Geldverstrekkers kunnen nader onderzoek of sanering eisen. Informatie is vaak beschikbaar via de gemeente of provincie. Leg vast welke informatie is opgevraagd.`,tags:['bodem','verontreiniging','onderpand'],bron:''},
 {id:'hwx-076',thema:'hypotheek-nhg-woning',vraag:'Waarom is de eigendomssituatie van de grond belangrijk?',antwoord:`Een woning op eigen grond geeft volledig eigendom. Bij erfpacht of opstalrecht gelden andere voorwaarden en kosten. Ook gedeeltelijke eigendom of gemeentegrond in gebruik komt voor. Controleer dit voor de financiering.`,tags:['grond','eigendom','opstalrecht'],bron:'Kadaster'},
 {id:'hwx-077',thema:'hypotheek-nhg-woning',vraag:'Wat is een opstalrecht?',antwoord:`Bij een opstalrecht is iemand eigenaar van de opstal, maar niet van de grond eronder. Dit komt bijvoorbeeld voor bij woningen op grond van een woningcorporatie of bij zonnepanelen. Geldverstrekkers stellen eisen aan de duur en voorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['opstalrecht','grond','onderpand'],bron:''},
 {id:'hwx-078',thema:'hypotheek-nhg-woning',vraag:'Kan een geldverstrekker afwijzen omdat het onderpand courant genoeg moet zijn?',antwoord:`Ja. Geldverstrekkers beoordelen de verkoopbaarheid van het onderpand. Bijzondere woningen, zoals afgelegen of zeer specifieke panden, kunnen lastig te financieren zijn. Soms gelden een lagere LTV of extra voorwaarden. Leg de beoordeling vast.`,tags:['courantheid','onderpand','ltv'],bron:''},
 {id:'hwx-079',thema:'hypotheek-nhg-woning',vraag:'Wat is een incourant onderpand en wat zijn de gevolgen?',antwoord:`Een incourant onderpand is moeilijk verkoopbaar door ligging, type of gebruik. De geldverstrekker kan een lagere lening, een hogere rente of afwijzing hanteren. Ook de taxatie kan een langere verkooptijd noemen. Bespreek dit met de klant voor het bieden.`,tags:['incourant','onderpand','verkoopbaarheid'],bron:''},
 {id:'hwx-080',thema:'hypotheek-nhg-woning',vraag:'Wat betekent de verwachte verkooptijd in het taxatierapport?',antwoord:`De taxateur schat hoe lang verkoop van de woning duurt bij een marktconforme prijs. Een lange verkooptijd wijst op een minder courant object. Geldverstrekkers kunnen dit meewegen in de acceptatie. Het is ook relevant voor de klant bij een latere verhuizing.`,tags:['taxatie','verkooptijd','courantheid'],bron:''},
 {id:'hwx-081',thema:'hypotheek-nhg-woning',vraag:'Mag de taxatie plaatsvinden voordat de koopovereenkomst is getekend?',antwoord:`Ja, dat kan. Sommige kopers laten vooraf taxeren om het risico te beperken. Het rapport moet wel de juiste koopsom en gegevens bevatten. Een herziening na ondertekening kan nodig zijn.`,tags:['taxatie','timing','koopovereenkomst'],bron:''},
 {id:'hwx-082',thema:'hypotheek-nhg-woning',vraag:'Wat als koopsom en taxatie verschillende roerende zaken bevatten?',antwoord:`Roerende zaken, zoals meubels, vallen buiten de marktwaarde van de woning. Een deel van de koopsom dat voor roerende zaken is, is in de regel niet te financieren met de hypotheek. Laat de koopovereenkomst de verdeling duidelijk vermelden. Leg de keuze vast.`,tags:['roerende zaken','koopsom','financiering'],bron:''},
 {id:'hwx-083',thema:'hypotheek-nhg-woning',vraag:'Is de vergoeding voor roerende zaken fiscaal relevant?',antwoord:`Ja. Over roerende zaken is geen overdrachtsbelasting verschuldigd, mits de waarde reëel is. Ook is een lening voor roerende zaken geen eigenwoningschuld. Een te hoge waarde kan door de Belastingdienst worden gecorrigeerd. Verwijs voor de fiscale beoordeling naar de notaris of Belastingdienst.`,tags:['roerende zaken','overdrachtsbelasting','fiscaal'],bron:'Belastingdienst'},
 {id:'hwx-084',thema:'hypotheek-nhg-woning',vraag:'Hoe financier je een woning met een bijgebouw dat apart wordt bewoond?',antwoord:`Als een bijgebouw zelfstandig wordt bewoond, kan het als gedeeltelijke verhuur of een tweede woning worden gezien. Dat beïnvloedt de financierbaarheid en de fiscale eigenwoningregeling. Ook het omgevingsplan moet dit gebruik toestaan. Controleer de voorwaarden van de geldverstrekker.`,tags:['bijgebouw','mantelzorg','gebruik'],bron:''},
 {id:'hwx-085',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning met een garage die als woonruimte is ingericht?',antwoord:`Een omgebouwde garage kan vergunningplichtig zijn geweest. De taxateur waardeert de ruimte mogelijk niet als woonruimte. Ook isolatie en ventilatie kunnen onvoldoende zijn. Laat de klant de vergunning en de staat nagaan.`,tags:['garage','woonruimte','vergunning'],bron:''},
 {id:'hwx-086',thema:'hypotheek-nhg-woning',vraag:'Wat is een woning met een woonwerkbestemming?',antwoord:`Bij een woonwerkbestemming zijn wonen en werken in één object toegestaan. De financiering hangt af van de verdeling tussen woon- en bedrijfsdeel. Het bedrijfsdeel valt niet onder de eigenwoningregeling. Controleer de voorwaarden van de geldverstrekker en leg de verdeling vast.`,tags:['woonwerk','gemengd gebruik','bestemming'],bron:''},
 {id:'hwx-087',thema:'hypotheek-nhg-woning',vraag:'Kan een geldverstrekker een agrarische woning financieren?',antwoord:`Een woning met agrarische bestemming kan lastiger zijn, zeker als de woning losstaat van een bedrijf. De taxateur toetst of burgerbewoning is toegestaan. Geldverstrekkers stellen vaak aanvullende eisen. Controleer het omgevingsplan en de voorwaarden van de geldverstrekker.`,tags:['agrarisch','bestemming','burgerbewoning'],bron:''},
 {id:'hwx-088',thema:'hypotheek-nhg-woning',vraag:'Wat is een woning met een zogenoemde plattelandswoning-status?',antwoord:`Dat is een voormalige agrarische bedrijfswoning die door derden mag worden bewoond, met beperkte bescherming tegen bedrijfshinder. De gemeente bepaalt die status. Het kan waarde en verkoopbaarheid beïnvloeden. Controleer de status en leg die vast.`,tags:['plattelandswoning','agrarisch','status'],bron:''},
 {id:'hwx-089',thema:'hypotheek-nhg-woning',vraag:'Hoe reken je de LTV bij aankoop met verbouwing?',antwoord:`De LTV is de hoogte van de lening gedeeld door de marktwaarde na verbouwing, zoals bepaald door de taxateur. De leningruimte volgt uit de normen. Rekenvoorbeeld: een lening van 300 bij een waarde na verbouwing van 300 geeft een LTV van 100%. Gebruik altijd de waarde uit het gevalideerde rapport.`,tags:['ltv','verbouwing','rekenvoorbeeld'],bron:'Trhk'},
 {id:'hwx-090',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met schade aan de woning tussen koop en levering?',antwoord:`De koopovereenkomst regelt in de regel wie het risico draagt tot de levering. Vaak ligt dat bij de verkoper tot de sleuteloverdracht. Schade kan gevolgen hebben voor de waarde en de financiering. Laat de klant de woning voor levering controleren en informeer bij twijfel de notaris.`,tags:['levering','schade','risico'],bron:''},
 {id:'hwx-091',thema:'hypotheek-nhg-woning',vraag:'Welke informatie geef je de taxateur mee bij een opdracht?',antwoord:`Geef koopsom, koopovereenkomst, bekende gebreken, verbouwingsplannen en verduurzamingsmaatregelen door. Vermeld erfpacht en VvE-gegevens als die er zijn. Zo sluit het rapport aan bij de aanvraag. Leg vast wat je hebt aangeleverd.`,tags:['taxatie','opdracht','gegevens'],bron:''},
 {id:'hwx-092',thema:'hypotheek-nhg-woning',vraag:'Wat is mandeligheid en waarom is die relevant?',antwoord:`Mandeligheid is gezamenlijk eigendom van een zaak die bij meerdere percelen hoort, zoals een gedeelde oprit of brandgang. De eigenaren dragen samen de kosten van onderhoud. Mandeligheid gaat mee over bij verkoop. Signaleer het en bespreek de praktische gevolgen.`,tags:['mandeligheid','gedeeld eigendom','perceel'],bron:'BW'},
 {id:'hwx-093',thema:'hypotheek-nhg-woning',vraag:'Kan een woning met een lopende huurovereenkomst als eigen woning worden gekocht?',antwoord:`De koper krijgt de woning dan in verhuurde staat en kan er vaak niet direct in. Financiering als eigen woning is dan meestal niet mogelijk. Er gelden aparte regels en een lagere waarde. Leg de status vast en controleer de voorwaarden van de geldverstrekker.`,tags:['verhuurd','eigen woning','financiering'],bron:''},
 {id:'hwx-094',thema:'hypotheek-nhg-woning',vraag:'Wat is een anti-speculatiebeding?',antwoord:`Dat is een beding van de verkoper, vaak een gemeente of ontwikkelaar, dat doorverkoop binnen een periode beperkt of een boete oplegt. Het kan ook een zelfbewoningsplicht bevatten. Dit beïnvloedt de flexibiliteit van de klant. Bespreek het en leg vast dat de klant het begrijpt.`,tags:['anti-speculatiebeding','zelfbewoningsplicht','akte'],bron:''},
 {id:'hwx-095',thema:'hypotheek-nhg-woning',vraag:'Wat is een zelfbewoningsplicht?',antwoord:`Een zelfbewoningsplicht verplicht de koper de woning zelf te bewonen, vaak voor een vaste periode. Gemeenten kunnen dit opleggen bij bepaalde woningen. Verhuur is dan niet of beperkt toegestaan. Controleer de akte en de gemeentelijke regels.`,tags:['zelfbewoningsplicht','verhuur','gemeente'],bron:''},
 {id:'hwx-096',thema:'hypotheek-nhg-woning',vraag:'Waarom moet je de koopovereenkomst controleren voordat je de taxatie aanvraagt?',antwoord:`De koopovereenkomst bevat koopsom, roerende zaken, ontbindende voorwaarden en bijzondere bepalingen. Fouten in die gegevens werken door in het rapport. Ook bijzondere bedingen, zoals erfpacht of anti-speculatie, moeten in het rapport komen. Controleer dit vooraf.`,tags:['koopovereenkomst','taxatie','controle'],bron:''},
 {id:'hwx-097',thema:'hypotheek-nhg-woning',vraag:'Wat doe je als de woning een andere kadastrale grootte heeft dan in de verkoopbrochure?',antwoord:`Bij twijfel laat je de klant het kadastrale perceel controleren. Verschillen kunnen ontstaan door oude metingen of gebruik van grond die niet is gekocht. De koper betaalt alleen voor wat in de akte staat. Bespreek dit voor ondertekening.`,tags:['kadaster','perceel','brochure'],bron:'Kadaster'},
 {id:'hwx-098',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met grond die de verkoper in gebruik heeft maar niet bezit?',antwoord:`Grond van de gemeente of buren in gebruik gaat niet automatisch over. Er kan sprake zijn van verjaring of een huurafspraak. Dit heeft gevolgen voor waarde en gebruik. Laat de notaris dit uitzoeken en leg de uitkomst vast.`,tags:['grond','verjaring','gebruik'],bron:''},
 {id:'hwx-099',thema:'hypotheek-nhg-woning',vraag:'Kan een woning met een geplande sloop of herstructurering worden gefinancierd?',antwoord:`Bij bekende sloop- of herstructureringsplannen is financiering vaak beperkt of onmogelijk. De taxateur hoort dit te vermelden. Informatie staat vaak bij de gemeente. Bespreek het risico en controleer de voorwaarden van de geldverstrekker.`,tags:['sloop','herstructurering','onderpand'],bron:''},
 {id:'hwx-100',thema:'hypotheek-nhg-woning',vraag:'Wat betekent een opmerking in het rapport over geluidsoverlast of hoogspanning?',antwoord:`Omgevingsfactoren zoals geluid, hoogspanning of geur kunnen de waarde en verkoopbaarheid drukken. De taxateur neemt dit mee in de waardering. Het kan ook gevolgen hebben voor de courantheid. Bespreek het met de klant en leg dat vast.`,tags:['omgeving','overlast','waarde'],bron:''},
 {id:'hwx-101',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een bouwkundige keuring en een taxatie?',antwoord:`Een taxatie bepaalt de marktwaarde van de woning. Een bouwkundige keuring beoordeelt de technische staat en de herstelkosten. De taxateur kijkt alleen globaal naar gebreken. Voor een goed beeld van risico’s zijn beide nodig.`,tags:['bouwkundige keuring','taxatie','verschil'],bron:''},
 {id:'hwx-102',thema:'hypotheek-nhg-woning',vraag:'Wanneer adviseer je een klant om voor het bieden een bouwkundige keuring te laten doen?',antwoord:`Bij oudere woningen, zichtbare gebreken of twijfel over fundering is een keuring vooraf verstandig. In een krappe markt wordt vaak zonder voorbehoud geboden. Dan is een keuring vooraf de enige manier om het risico te kennen. Leg vast dat je de klant hierop hebt gewezen.`,tags:['bouwkundige keuring','bieden','voorbehoud'],bron:''},
 {id:'hwx-103',thema:'hypotheek-nhg-woning',vraag:'Wat is een ontbindende voorwaarde bouwkundige keuring?',antwoord:`Met deze voorwaarde kan de koper de koop ontbinden als de keuring ernstige gebreken oplevert. De voorwaarde moet duidelijk omschrijven wat als ernstig geldt, bijvoorbeeld een bedrag aan herstelkosten. Zonder heldere omschrijving ontstaan discussies. Laat de klant dit met de makelaar regelen.`,tags:['ontbindende voorwaarde','keuring','koopovereenkomst'],bron:''},
 {id:'hwx-104',thema:'hypotheek-nhg-woning',vraag:'Hoe oud mag een bouwkundig rapport zijn voor de financiering?',antwoord:`Een vaste wettelijke termijn is er niet. Geldverstrekkers en NHG kunnen eisen stellen aan de datum van het rapport. Bij een oud rapport kan de staat van de woning veranderd zijn. Controleer de voorwaarden van de geldverstrekker.`,tags:['bouwkundig rapport','geldigheid','datum'],bron:''},
 {id:'hwx-105',thema:'hypotheek-nhg-woning',vraag:'Kan de klant herstelkosten uit een keuring meefinancieren?',antwoord:`Dat kan vaak via een bouwdepot als onderdeel van de verbouwing. De taxateur bepaalt dan de waarde na herstel. De lening moet binnen de LTV en de normen passen. Controleer de voorwaarden van de geldverstrekker.`,tags:['herstelkosten','bouwdepot','financiering'],bron:''},
 {id:'hwx-106',thema:'hypotheek-nhg-woning',vraag:'Wat is een bouwkundig rapport volgens een vast model?',antwoord:`Er bestaan standaardmodellen die eisen stellen aan inhoud en opbouw, bijvoorbeeld bij NHG-aanvragen. Een rapport volgens zo een model is beter vergelijkbaar en wordt eerder geaccepteerd. Controleer welke eisen de geldverstrekker of NHG stelt. Vraag het juiste model aan.`,tags:['bouwkundig rapport','model','eisen'],bron:'NHG'},
 {id:'hwx-107',thema:'hypotheek-nhg-woning',vraag:'Wat doe je als het bouwkundig rapport veel gebreken noemt die de taxateur niet ziet?',antwoord:`Bespreek de verschillen met de klant. De taxatiewaarde kan te hoog zijn als gebreken niet zijn meegenomen. Informeer de geldverstrekker bij wezenlijke gebreken. Leg vast welke informatie is gedeeld.`,tags:['bouwkundig rapport','taxatie','gebreken'],bron:''},
 {id:'hwx-108',thema:'hypotheek-nhg-woning',vraag:'Is de verkoper aansprakelijk voor verborgen gebreken?',antwoord:`De verkoper heeft een mededelingsplicht voor gebreken die hij kent. De koper heeft een onderzoeksplicht. Wat redelijkerwijs ontdekt had kunnen worden, valt vaak voor rekening van de koper. Verwijs bij een geschil naar een juridisch adviseur.`,tags:['verborgen gebreken','mededelingsplicht','onderzoeksplicht'],bron:'BW'},
 {id:'hwx-109',thema:'hypotheek-nhg-woning',vraag:'Wat is de onderzoeksplicht van de koper en hoe raakt die het advies?',antwoord:`De koper moet zelf redelijk onderzoek doen naar de staat van de woning. Een bouwkundige keuring helpt aan die plicht te voldoen. Zonder keuring is het moeilijker om de verkoper aan te spreken. Wijs de klant hierop en leg dat vast.`,tags:['onderzoeksplicht','keuring','koper'],bron:'BW'},
 {id:'hwx-110',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een ouderdomsclausule in de koopovereenkomst?',antwoord:`Een ouderdomsclausule beperkt de aansprakelijkheid van de verkoper voor gebreken die bij oudere woningen te verwachten zijn. Het risico op herstelkosten ligt dan meer bij de koper. Dat versterkt het belang van een keuring. Bespreek dit met de klant.`,tags:['ouderdomsclausule','gebreken','koopovereenkomst'],bron:''},
 {id:'hwx-111',thema:'hypotheek-nhg-woning',vraag:'Wat is een asbestclausule?',antwoord:`Met een asbestclausule verklaart de koper bekend te zijn met mogelijk asbest en neemt hij het risico. De koper kan de verkoper dan meestal niet aanspreken. Bij verbouwing kunnen saneringskosten hoog zijn. Neem dit mee in het budget.`,tags:['asbestclausule','asbest','koopovereenkomst'],bron:''},
 {id:'hwx-112',thema:'hypotheek-nhg-woning',vraag:'Welke funderingstypen kom je vaak tegen bij oudere woningen?',antwoord:`Veel voorkomende types zijn een fundering op staal, op houten palen en op betonnen palen. Houten palen zijn gevoelig voor droogstand en paalrot. Een fundering op staal kan gevoelig zijn voor verschilzetting. Het type bepaalt mede het risico en de eventuele herstelkosten.`,tags:['fundering','houten palen','typen'],bron:''},
 {id:'hwx-113',thema:'hypotheek-nhg-woning',vraag:'Wat is droogstand bij een houten paalfundering?',antwoord:`Bij droogstand komen de koppen van houten palen boven het grondwater uit. Daardoor kan schimmelaantasting en rot ontstaan. Dit kan leiden tot verzakking en hoge herstelkosten. Het risico hangt af van de grondwaterstand in het gebied.`,tags:['droogstand','houten palen','fundering'],bron:''},
 {id:'hwx-114',thema:'hypotheek-nhg-woning',vraag:'Waar vind je informatie over funderingsrisico in een gebied?',antwoord:`Gemeenten hebben vaak een funderingsloket of informatie over risicogebieden. Er bestaan ook landelijke kaarten en databanken. Een funderingsonderzoek geeft per woning meer zekerheid. Leg vast welke bronnen je hebt geraadpleegd.`,tags:['fundering','informatie','gemeente'],bron:'KCAF'},
 {id:'hwx-115',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een funderingsquickscan en een volledig funderingsonderzoek?',antwoord:`Een quickscan is een eerste inschatting op basis van bekende gegevens en uiterlijke kenmerken. Een volledig onderzoek kan inspectieputten, metingen en houtonderzoek omvatten. Het volledig onderzoek geeft meer zekerheid over de staat. De geldverstrekker bepaalt welk onderzoek nodig is.`,tags:['funderingsonderzoek','quickscan','inspectie'],bron:''},
 {id:'hwx-116',thema:'hypotheek-nhg-woning',vraag:'Wat is een funderingslabel?',antwoord:`Een funderingslabel geeft een indicatie van de kwaliteit of het risico van de fundering. Het is een initiatief in de markt en geen wettelijk verplicht label. Niet alle geldverstrekkers gebruiken het. Controleer welke informatie de geldverstrekker accepteert.`,tags:['funderingslabel','fundering','informatie'],bron:''},
 {id:'hwx-117',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er als de fundering moet worden hersteld bij een rijtjeshuis?',antwoord:`Funderingsherstel gebeurt vaak per blok of straat, omdat woningen constructief verbonden zijn. Dat vraagt samenwerking met buren en soms de gemeente. Kosten en planning zijn dan minder in eigen hand. Bespreek dit risico met de klant.`,tags:['funderingsherstel','rijtjeshuis','buren'],bron:''},
 {id:'hwx-118',thema:'hypotheek-nhg-woning',vraag:'Bestaan er regelingen voor financiering van funderingsherstel?',antwoord:`Er zijn gemeentelijke en landelijke regelingen, zoals een fonds voor funderingsherstel. De voorwaarden en beschikbaarheid verschillen per gemeente en periode. Verwijs de klant naar de gemeente of het fonds. Leg vast welke regelingen zijn onderzocht.`,tags:['funderingsherstel','fonds','regeling'],bron:'Fonds Duurzaam Funderingsherstel'},
 {id:'hwx-119',thema:'hypotheek-nhg-woning',vraag:'Kan een geldverstrekker na aankoop eisen dat de fundering wordt hersteld?',antwoord:`Na aankoop kan de geldverstrekker de klant meestal niet zomaar verplichten. De voorwaarden kunnen wel bepalen dat de klant het onderpand goed onderhoudt. Bij aankoop met bekende problemen stelt de geldverstrekker vaak vooraf voorwaarden. Lees de algemene voorwaarden en leg ze uit.`,tags:['fundering','voorwaarden','onderhoudsplicht'],bron:''},
 {id:'hwx-120',thema:'hypotheek-nhg-woning',vraag:'Wat is het risico van een woning met scheuren in de gevel?',antwoord:`Scheuren kunnen wijzen op zetting of funderingsproblemen, maar ook op krimp of thermische werking. Alleen een deskundige kan de oorzaak bepalen. Bij twijfel is een bouwkundig of funderingsonderzoek verstandig. Leg vast dat je dit hebt geadviseerd.`,tags:['scheuren','fundering','keuring'],bron:''},
 {id:'hwx-121',thema:'hypotheek-nhg-woning',vraag:'Waarom zijn woningen uit de jaren zestig en zeventig vaak aandachtspunten?',antwoord:`In die periode werd soms asbest toegepast en was de isolatie beperkt. Ook kunnen er specifieke constructieve aandachtspunten zijn. Verduurzaming vraagt vaak grotere ingrepen. Laat dit meewegen in het budget en de keuring.`,tags:['bouwjaar','asbest','isolatie'],bron:''},
 {id:'hwx-122',thema:'hypotheek-nhg-woning',vraag:'Wat is een systeemwoning?',antwoord:`Een systeemwoning is gebouwd met een industrieel bouwsysteem, vaak met geprefabriceerde betonelementen. Sommige systemen kennen bekende constructieve gebreken. Geldverstrekkers kunnen extra onderzoek eisen. Controleer de voorwaarden van de geldverstrekker.`,tags:['systeemwoning','betonsysteem','bouwwijze'],bron:''},
 {id:'hwx-123',thema:'hypotheek-nhg-woning',vraag:'Kan een houtskeletbouwwoning normaal worden gefinancierd?',antwoord:`Ja, houtskeletbouw is een gangbare bouwwijze. De taxateur beoordeelt de staat en het onderhoud. Bij oudere of bijzondere constructies kan extra onderzoek nodig zijn. Controleer de voorwaarden van de geldverstrekker.`,tags:['houtskeletbouw','bouwwijze','financiering'],bron:''},
 {id:'hwx-124',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een tiny house?',antwoord:`Een tiny house heeft vaak geen eigen grond of een tijdelijke plek. Financiering als eigen woning met hypotheekrecht is dan lastig. Er gelden eisen aan vergunning en permanente bewoning. Controleer de voorwaarden van de geldverstrekker.`,tags:['tiny house','woningtype','financiering'],bron:''},
 {id:'hwx-125',thema:'hypotheek-nhg-woning',vraag:'Kan een woonwagen met standplaats als eigen woning worden gefinancierd?',antwoord:`Dat hangt af van de vraag of het een onroerende zaak is en of de standplaats zeker is. Veel geldverstrekkers financieren dit niet of beperkt. De fiscale eigenwoningregeling kan wel van toepassing zijn. Controleer de voorwaarden van de geldverstrekker.`,tags:['woonwagen','standplaats','onroerend'],bron:''},
 {id:'hwx-126',thema:'hypotheek-nhg-woning',vraag:'Wat is bijzonder aan een woning met een rieten dak?',antwoord:`Een rieten dak vraagt specifiek onderhoud en heeft een hoger brandrisico. De opstalverzekering kan duurder zijn of extra eisen stellen. Taxateurs letten op de staat van het riet. Laat de klant de verzekerbaarheid vooraf controleren.`,tags:['rieten dak','opstalverzekering','onderhoud'],bron:''},
 {id:'hwx-127',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een bouwkundig rapport en een energieadvies?',antwoord:`Een bouwkundig rapport beschrijft de technische staat en herstelkosten. Een energieadvies beschrijft de energieprestatie en mogelijke besparende maatregelen. Beide kunnen elkaar aanvullen bij een verbouwing. Bepaal per dossier welk document nodig is.`,tags:['bouwkundig rapport','energieadvies','verschil'],bron:''},
 {id:'hwx-128',thema:'hypotheek-nhg-woning',vraag:'Wat is het risico van een woning met een ondergrondse olietank?',antwoord:`Een oude olietank kan lekken en bodemverontreiniging veroorzaken. Verwijdering of sanering kan kosten geven. Informatie is soms bekend bij de gemeente. Adviseer de klant dit na te gaan en leg dat vast.`,tags:['olietank','bodem','sanering'],bron:''},
 {id:'hwx-129',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning boven een winkel?',antwoord:`Een woning boven een winkel kan te maken hebben met gedeelde voorzieningen en een VvE. Er kunnen geluid en brandrisico zijn. Ook de bereikbaarheid en eigen opgang zijn relevant. Laat de taxateur dit beoordelen en controleer de VvE-situatie.`,tags:['bovenwoning','winkel','vve'],bron:''},
 {id:'hwx-130',thema:'hypotheek-nhg-woning',vraag:'Wat is een bovenwoning zonder VvE en waarom is dat relevant?',antwoord:`Soms is een pand niet gesplitst of is de VvE niet actief. Gezamenlijk onderhoud is dan slecht geregeld. Geldverstrekkers kunnen dit als risico zien. Controleer de splitsing en de status van de VvE.`,tags:['vve','slapende vve','bovenwoning'],bron:''},
 {id:'hwx-131',thema:'hypotheek-nhg-woning',vraag:'Wat is een woning met kelder en waar let je op?',antwoord:`Een kelder kan vochtproblemen hebben en vraagt goede afwatering. In sommige gebieden is grondwater een risico. De taxateur kan nader onderzoek adviseren. Leg de bevindingen vast.`,tags:['kelder','vocht','grondwater'],bron:''},
 {id:'hwx-132',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning in een overstromingsgevoelig gebied?',antwoord:`Overstromingsrisico kan de verzekerbaarheid en waarde beïnvloeden. Veel opstalpolissen dekken overstroming niet of beperkt. Informatie over risicogebieden is openbaar beschikbaar. Bespreek dit met de klant en leg dat vast.`,tags:['overstroming','klimaatrisico','verzekering'],bron:''},
 {id:'hwx-133',thema:'hypotheek-nhg-woning',vraag:'Waarom vragen geldverstrekkers steeds vaker naar het klimaatrisico van het onderpand?',antwoord:`Klimaatrisico’s zoals overstroming, droogte en hitte kunnen de waarde op termijn beïnvloeden. Toezichthouders vragen banken om dit risico in kaart te brengen. Dat kan doorwerken in acceptatie of voorwaarden. Bespreek relevante risico’s met de klant.`,tags:['klimaatrisico','acceptatie','onderpand'],bron:'DNB'},
 {id:'hwx-134',thema:'hypotheek-nhg-woning',vraag:'Kan een geldverstrekker een monument anders beoordelen dan een gewone woning?',antwoord:`Ja. Monumenten hebben beperkingen bij verbouwing en vaak hogere onderhoudskosten. Dit kan de waarde en de verkoopbaarheid beïnvloeden. Sommige geldverstrekkers stellen extra eisen. Controleer de voorwaarden van de geldverstrekker.`,tags:['monument','waardering','onderhoud'],bron:''},
 {id:'hwx-135',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een rijksmonument en een gemeentelijk monument?',antwoord:`Een rijksmonument is door het Rijk aangewezen, een gemeentelijk monument door de gemeente. De regels voor vergunningen en eventuele subsidies verschillen. Bij beide gelden beperkingen bij verbouwing. Controleer de status bij gemeente of Rijksdienst.`,tags:['monument','rijksmonument','vergunning'],bron:'RCE'},
 {id:'hwx-136',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een woning in een beschermd stads- of dorpsgezicht?',antwoord:`In zo een gebied gelden extra regels voor uiterlijke wijzigingen. Dit kan verduurzaming bemoeilijken, zoals zonnepanelen aan de voorzijde. Controleer de regels bij de gemeente. Neem dit mee in plannen voor verbouwing.`,tags:['beschermd gezicht','vergunning','verduurzaming'],bron:''},
 {id:'hwx-137',thema:'hypotheek-nhg-woning',vraag:'Wat is een 2-onder-1-kap-woning met gedeelde fundering en wat betekent dat?',antwoord:`Bij gedeelde funderingen of constructies kan herstel samen met de buren moeten gebeuren. Gebreken bij de buren kunnen effect hebben op de eigen woning. Een keuring kan dit signaleren. Bespreek dit risico met de klant.`,tags:['twee-onder-een-kap','fundering','buren'],bron:''},
 {id:'hwx-138',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij de aankoop van een kluswoning?',antwoord:`Een kluswoning vraagt een realistische begroting en een buffer voor tegenvallers. De taxateur bepaalt de waarde na verbouwing. Het bouwdepot moet aansluiten bij de begroting. Leg de begroting, de planning en de buffer vast.`,tags:['kluswoning','begroting','bouwdepot'],bron:''},
 {id:'hwx-139',thema:'hypotheek-nhg-woning',vraag:'Hoe voorkom je dat de klant te weinig buffer heeft bij een kluswoning?',antwoord:`Adviseer naast het bouwdepot een eigen buffer voor onverwachte kosten. Tegenvallers komen bij oudere woningen vaak voor. Reken scenario’s door met hogere kosten. Leg het advies over de buffer vast.`,tags:['kluswoning','buffer','tegenvallers'],bron:''},
 {id:'hwx-140',thema:'hypotheek-nhg-woning',vraag:'Wat is een woning met een erfdienstbaarheid voor nutsleidingen?',antwoord:`Netbeheerders kunnen een recht hebben op leidingen over of onder het perceel. Dat beperkt bouwen op die plek. Het staat vaak in het kadaster of de akte. Signaleer het bij uitbreidingsplannen.`,tags:['erfdienstbaarheid','leidingen','perceel'],bron:'Kadaster'},
 {id:'hwx-141',thema:'hypotheek-nhg-woning',vraag:'Kan een woning met een vergunningsplichtige uitbouw zonder vergunning worden gefinancierd?',antwoord:`Een uitbouw zonder vereiste vergunning kan gevolgen hebben voor waarde en handhaving. De taxateur kan dit niet altijd zien. Geldverstrekkers kunnen het onderdeel niet meewaarderen of voorwaarden stellen. Laat de klant de vergunningen controleren.`,tags:['vergunning','uitbouw','handhaving'],bron:'Omgevingswet'},
 {id:'hwx-142',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een appartement in een voormalig kantoorgebouw?',antwoord:`Bij transformatie zijn bouwkwaliteit, geluidsisolatie en VvE-structuur aandachtspunten. Soms is de VvE nog jong en heeft weinig reserves. Controleer het onderhoudsplan en de opleveringsgaranties. Leg de bevindingen vast.`,tags:['transformatie','appartement','vve'],bron:''},
 {id:'hwx-143',thema:'hypotheek-nhg-woning',vraag:'Wat is een woning met gedeelde ingang of gemeenschappelijke ruimtes?',antwoord:`Gemeenschappelijke ruimtes vragen afspraken over gebruik en onderhoud. Dat is meestal in een splitsingsakte of reglement geregeld. Zonder heldere afspraken ontstaat risico op conflicten en kosten. Controleer de documenten.`,tags:['gemeenschappelijke ruimte','splitsingsakte','appartement'],bron:''},
 {id:'hwx-144',thema:'hypotheek-nhg-woning',vraag:'Wat is een benedenwoning met tuin in appartementsrecht?',antwoord:`Ook een benedenwoning kan een appartementsrecht zijn met een VvE. Het gebruik van de tuin is dan vaak een exclusief gebruiksrecht. De VvE kan regels stellen over gebruik en onderhoud. Controleer de splitsingsakte.`,tags:['benedenwoning','appartementsrecht','tuin'],bron:''},
 {id:'hwx-145',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een woning waarbij de verkoper een bouwkundig rapport aanbiedt?',antwoord:`Een rapport van de verkoper is nuttig, maar is niet in opdracht van de koper opgesteld. De koper kan er beperkt rechten aan ontlenen. Adviseer om te controleren hoe recent en volledig het is. Een eigen keuring blijft aan te raden.`,tags:['bouwkundig rapport','verkoper','onafhankelijkheid'],bron:''},
 {id:'hwx-146',thema:'hypotheek-nhg-woning',vraag:'Welke rol speelt de leeftijd van de cv-ketel of installaties in het advies?',antwoord:`Oude installaties kunnen binnenkort vervangen moeten worden. Dat raakt de woonlasten en het budget. Bij verduurzaming kan vervanging juist een kans zijn. Neem de verwachte kosten mee in het gesprek.`,tags:['installaties','onderhoud','budget'],bron:''},
 {id:'hwx-147',thema:'hypotheek-nhg-woning',vraag:'Wat is loodhoudende leidingwaterinstallatie en waarom signaleer je die?',antwoord:`In oudere woningen kunnen nog loden waterleidingen zitten. Dat kan gezondheidsrisico geven en vervanging nodig maken. Een keuring kan dit signaleren. Neem de kosten mee in het budget.`,tags:['loden leidingen','oudere woning','keuring'],bron:''},
 {id:'hwx-148',thema:'hypotheek-nhg-woning',vraag:'Wat zijn veelgemaakte fouten bij het beoordelen van het onderpand?',antwoord:`Adviseurs vertrouwen soms alleen op de taxatie en missen bouwkundige risico’s. Bijzondere bedingen in de akte worden niet gelezen. Gebruik in strijd met het omgevingsplan wordt niet gesignaleerd. Een checklist per dossier helpt dit te voorkomen.`,tags:['onderpand','fouten','checklist'],bron:''},
 {id:'hwx-149',thema:'hypotheek-nhg-woning',vraag:'Hoe leg je de bespreking van bouwkundige gebreken vast in het dossier?',antwoord:`Noteer welke rapporten beschikbaar waren en welke risico’s zijn besproken. Leg vast of de klant een keuring heeft gekozen of afgeslagen. Vermeld de gevolgen die je hebt toegelicht. Zo is je advies later te reconstrueren.`,tags:['vastlegging','bouwkundig','dossier'],bron:''},
 {id:'hwx-150',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning met een plat dak?',antwoord:`Een plat dak vraagt periodiek onderhoud en de dakbedekking heeft een beperkte levensduur. Lekkage kan tot vervolgschade leiden. Een keuring geeft inzicht in de staat en de resterende levensduur. Neem vervanging mee in het budget als die op korte termijn nodig is.`,tags:['plat dak','onderhoud','keuring'],bron:''},
 {id:'hwx-151',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen voortdurende en eeuwigdurende erfpacht?',antwoord:`Bij voortdurende erfpacht loopt het recht door, maar wordt de canon periodiek herzien. Bij eeuwigdurende erfpacht is het recht onbeperkt in tijd, met of zonder herzieningen. De precieze betekenis hangt af van de algemene bepalingen van de erfverpachter. Lees altijd de akte en de toepasselijke bepalingen.`,tags:['erfpacht','voortdurend','eeuwigdurend'],bron:''},
 {id:'hwx-152',thema:'hypotheek-nhg-woning',vraag:'Wat betekent indexatie van de erfpachtcanon?',antwoord:`Bij indexatie stijgt de canon periodiek mee met een index, zoals inflatie. Dit staat in de akte of de algemene bepalingen. De canon stijgt dus ook tussen herzieningen in. Neem een realistische stijging mee in het gesprek over woonlasten.`,tags:['erfpacht','indexatie','canon'],bron:''},
 {id:'hwx-153',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met erfpacht waarbij de nieuwe canon nog niet bekend is?',antwoord:`Als een herziening nabij is maar de canon nog niet is vastgesteld, is de woonlast onzeker. Geldverstrekkers kunnen dan van een indicatie of een hoger bedrag uitgaan. Bespreek scenario’s met een hogere canon. Controleer de voorwaarden van de geldverstrekker.`,tags:['erfpacht','onzekerheid','canon'],bron:''},
 {id:'hwx-154',thema:'hypotheek-nhg-woning',vraag:'Wat is een canonherziening en waarom is die een risico?',antwoord:`Bij een herziening wordt de canon opnieuw vastgesteld, vaak op basis van de grondwaarde op dat moment. De nieuwe canon kan veel hoger zijn. Dat raakt de woonlasten en de waarde van de woning. Breng de datum van de volgende herziening in kaart en leg die vast.`,tags:['erfpacht','canonherziening','woonlasten'],bron:''},
 {id:'hwx-155',thema:'hypotheek-nhg-woning',vraag:'Hoe neem je een toekomstige canonherziening mee in het advies?',antwoord:`Signaleer de datum en de methode van herziening uit de akte. Bespreek scenario’s met een hogere canon. Kijk of afkoop of overstap naar een ander stelsel mogelijk is. Leg vast hoe de klant dit risico heeft afgewogen.`,tags:['erfpacht','canonherziening','scenario'],bron:''},
 {id:'hwx-156',thema:'hypotheek-nhg-woning',vraag:'Wat is een erfpachtstelsel met overstapregeling?',antwoord:`Sommige gemeenten bieden een regeling om over te stappen van een tijdvak naar eeuwigdurende erfpacht. De voorwaarden en de termijn verschillen per gemeente. Overstappen kan lasten op lange termijn vastzetten. Verwijs naar de gemeente voor de actuele voorwaarden.`,tags:['erfpacht','overstap','gemeente'],bron:''},
 {id:'hwx-157',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een erfpachtrecht dat afloopt binnen de looptijd van de hypotheek?',antwoord:`Geldverstrekkers stellen eisen aan de resterende duur van het erfpachtrecht. Als het recht eerder afloopt dan de hypotheek, kan financiering lastig zijn. Bekijk de verlengingsmogelijkheden in de akte. Controleer de voorwaarden van de geldverstrekker.`,tags:['erfpacht','looptijd','verlenging'],bron:''},
 {id:'hwx-158',thema:'hypotheek-nhg-woning',vraag:'Wat staat er in de algemene bepalingen van erfpacht?',antwoord:`De algemene bepalingen regelen onder meer de canon, herziening, toegestaan gebruik en wat er gebeurt bij einde van het recht. Ze verschillen per erfverpachter en per jaartal. De akte verwijst naar de toepasselijke bepalingen. Lees ze zorgvuldig en vat de kern samen voor de klant.`,tags:['erfpacht','algemene bepalingen','akte'],bron:''},
 {id:'hwx-159',thema:'hypotheek-nhg-woning',vraag:'Kan een erfverpachter het recht opzeggen?',antwoord:`Opzegging door de erfverpachter is alleen mogelijk in de gevallen die de wet en de bepalingen noemen, zoals ernstige wanprestatie. Bij einde van het recht kan een vergoeding verschuldigd zijn. Geldverstrekkers letten op deze bepalingen. Laat bij twijfel een notaris meekijken.`,tags:['erfpacht','opzegging','erfverpachter'],bron:'BW'},
 {id:'hwx-160',thema:'hypotheek-nhg-woning',vraag:'Wat is een erfpachtrecht van een particuliere erfverpachter?',antwoord:`Naast gemeenten zijn er ook particuliere erfverpachters, zoals stichtingen of landgoederen. Hun voorwaarden kunnen afwijken van gemeentelijke regelingen. Herzieningen kunnen anders worden berekend. Controleer de akte en de voorwaarden van de geldverstrekker.`,tags:['erfpacht','particulier','voorwaarden'],bron:''},
 {id:'hwx-161',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er met erfpacht bij verkoop van de woning?',antwoord:`Het erfpachtrecht gaat over op de koper met de bestaande voorwaarden. Soms gelden bij overdracht nieuwe algemene bepalingen of een meldplicht aan de erfverpachter. Een afgekocht tijdvak gaat mee over. Controleer de akte en de bepalingen.`,tags:['erfpacht','verkoop','overdracht'],bron:''},
 {id:'hwx-162',thema:'hypotheek-nhg-woning',vraag:'Welke stukken vraag je op bij een woning met erfpacht?',antwoord:`Vraag de akte van erfpacht, de toepasselijke algemene bepalingen en het actuele canonbedrag op. Vraag ook naar afkoop, de afgekochte periode en de datum van herziening. Deze stukken zijn nodig voor taxatie en toets. Leg ze vast in het dossier.`,tags:['erfpacht','documenten','akte'],bron:''},
 {id:'hwx-163',thema:'hypotheek-nhg-woning',vraag:'Hoe verdeel je een verbouwing over bouwdepot en eigen geld?',antwoord:`Bepaal eerst welk deel binnen de normen en de LTV in het bouwdepot past. Het overige moet de klant met eigen middelen betalen. Eigen geld wordt vaak eerst besteed of als buffer gehouden. Leg de verdeling en de reden vast.`,tags:['bouwdepot','eigen geld','verbouwing'],bron:''},
 {id:'hwx-164',thema:'hypotheek-nhg-woning',vraag:'Mag het bouwdepot worden gebruikt voor iets anders dan opgegeven?',antwoord:`Uitgaven moeten aansluiten bij de verbouwing waarop de lening is gebaseerd. Wijzigingen kunnen vaak worden aangevraagd. Ook de fiscale aftrek hangt af van besteding aan de eigen woning. Laat wijzigingen vastleggen bij de geldverstrekker.`,tags:['bouwdepot','besteding','wijziging'],bron:''},
 {id:'hwx-165',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met prijsstijgingen tijdens een verbouwing?',antwoord:`Prijzen van materiaal en arbeid kunnen tijdens de verbouwing stijgen. Het bouwdepot wordt daardoor niet automatisch hoger. De klant moet het verschil zelf dragen of een verhoging aanvragen. Adviseer een buffer en leg dat advies vast.`,tags:['verbouwing','prijsstijging','buffer'],bron:''},
 {id:'hwx-166',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een vaste aanneemsom en werk in regie?',antwoord:`Bij een vaste aanneemsom zijn de kosten vooraf vastgelegd, behalve meer- en minderwerk. Bij werk in regie betaalt de klant op basis van bestede uren en materiaal. Regie geeft meer onzekerheid over het eindbedrag. Neem dit mee in de buffer.`,tags:['aanneemsom','regie','verbouwing'],bron:''},
 {id:'hwx-167',thema:'hypotheek-nhg-woning',vraag:'Wat zijn stelposten in een verbouwingsbegroting?',antwoord:`Stelposten zijn voorlopige bedragen voor onderdelen die nog niet zijn uitgewerkt. Het werkelijke bedrag kan hoger of lager uitvallen. Veel stelposten maken de begroting onzeker. Bespreek dit met de klant en houd rekening met een buffer.`,tags:['stelposten','begroting','verbouwing'],bron:''},
 {id:'hwx-168',thema:'hypotheek-nhg-woning',vraag:'Waarom is de opleverdatum in een aannemingsovereenkomst relevant voor de financiering?',antwoord:`De opleverdatum bepaalt hoe lang de klant dubbele lasten heeft. Ook moet de looptijd van het bouwdepot erbij aansluiten. Een vertraging kan extra kosten geven. Leg de datum vast en bespreek wat er gebeurt bij vertraging.`,tags:['oplevering','planning','bouwdepot'],bron:''},
 {id:'hwx-169',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen koop-aanneming en een bestaande woning bij financiering?',antwoord:`Bij koop-aanneming koopt de klant grond en sluit hij een aannemingsovereenkomst voor de bouw. Betalingen gaan in termijnen uit een bouwdepot. Er is vaak sprake van bouwrente en dubbele lasten. De waarde is meestal de koop-aanneemsom plus meerwerk.`,tags:['koop-aanneming','nieuwbouw','termijnen'],bron:''},
 {id:'hwx-170',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een verbouwing waarvoor de vergunning nog niet is verleend?',antwoord:`Zonder vergunning kan de verbouwing niet starten zoals gepland. Het bouwdepot loopt intussen wel. Bij weigering moet het plan worden aangepast, wat de waarde na verbouwing kan raken. Bespreek dit risico en controleer de voorwaarden van de geldverstrekker.`,tags:['vergunning','verbouwing','bouwdepot'],bron:'Omgevingswet'},
 {id:'hwx-171',thema:'hypotheek-nhg-woning',vraag:'Wat is minderwerk en welk effect heeft het?',antwoord:`Minderwerk verlaagt de aanneemsom, bijvoorbeeld als de klant zelf een keuken plaatst. Dat kan de waarde en de leenruimte verlagen. De klant moet dan de eigen kosten apart dekken. Bespreek de gevolgen voor de financiering.`,tags:['minderwerk','nieuwbouw','leenruimte'],bron:''},
 {id:'hwx-172',thema:'hypotheek-nhg-woning',vraag:'Wanneer gaat de rente lopen bij nieuwbouw?',antwoord:`De rente over de lening gaat lopen vanaf de notariële levering. Vanaf dat moment betaalt de klant rente over het hele bedrag, ook over het depot. Het depot levert depotrente op. De klant moet rekening houden met dubbele lasten tot oplevering.`,tags:['nieuwbouw','rente','levering'],bron:''},
 {id:'hwx-173',thema:'hypotheek-nhg-woning',vraag:'Waarom vallen bij nieuwbouw de notariële levering en de oplevering niet samen?',antwoord:`Bij nieuwbouw wordt de grond met de bouwtermijnen vaak al vroeg geleverd. De woning zelf wordt pas later opgeleverd. Tussen die momenten lopen rente en depot. Leg beide data vast in de planning van de klant.`,tags:['nieuwbouw','levering','oplevering'],bron:''},
 {id:'hwx-174',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning zonder aansluiting op het riool?',antwoord:`Sommige buitengebieden hebben een eigen voorziening voor afvalwater. Die vraagt onderhoud en kan vervangen moeten worden. De taxateur of keurder kan dit signaleren. Neem de kosten mee in het budget van de klant.`,tags:['riolering','buitengebied','onderhoud'],bron:''},
 {id:'hwx-175',thema:'hypotheek-nhg-woning',vraag:'Wat is een opschortende voorwaarde in een nieuwbouwovereenkomst?',antwoord:`Een opschortende voorwaarde laat de overeenkomst pas werken als bijvoorbeeld een bouwvergunning of voldoende verkoop is gerealiseerd. Tot dan is de start onzeker. Dit raakt de planning van de financiering. Leg de datum van vervulling vast.`,tags:['opschortende voorwaarde','nieuwbouw','planning'],bron:''},
 {id:'hwx-176',thema:'hypotheek-nhg-woning',vraag:'Wat betekent de vrij-op-naam-prijs bij nieuwbouw?',antwoord:`Vrij op naam betekent dat kosten zoals notaris voor levering en btw in de prijs zijn inbegrepen. De hypotheekakte en advieskosten zijn meestal niet inbegrepen. Bespreek welke kosten de klant nog heeft. Leg het overzicht vast.`,tags:['vrij op naam','nieuwbouw','kosten'],bron:''},
 {id:'hwx-177',thema:'hypotheek-nhg-woning',vraag:'Moet de klant bij nieuwbouw overdrachtsbelasting betalen?',antwoord:`Bij een nieuwe woning die nog niet in gebruik is genomen, is meestal btw verschuldigd in plaats van overdrachtsbelasting. Er zijn uitzonderingen, bijvoorbeeld bij grond. Laat de notaris de fiscale positie bepalen. Verwijs naar de Belastingdienst voor details.`,tags:['nieuwbouw','btw','overdrachtsbelasting'],bron:'Belastingdienst'},
 {id:'hwx-178',thema:'hypotheek-nhg-woning',vraag:'Wat is het belang van een energielabel bij nieuwbouw voor de leenruimte?',antwoord:`Nieuwbouw heeft vaak een zeer goed label. De Trhk koppelt extra leenruimte aan het energielabel. Bij een A++++ label met energieprestatiegarantie kan de extra ruimte het hoogst zijn. Controleer het definitieve label of de voorlopige berekening en leg die vast.`,tags:['nieuwbouw','energielabel','leenruimte'],bron:'Trhk'},
 {id:'hwx-179',thema:'hypotheek-nhg-woning',vraag:'Wat als het definitieve energielabel bij nieuwbouw lager uitvalt dan verwacht?',antwoord:`De extra leenruimte op basis van het label kan dan lager zijn. Dat kan de financiering raken als de klant de ruimte maximaal gebruikt. Bespreek dit risico bij krappe financiering. Controleer de voorwaarden van de geldverstrekker.`,tags:['energielabel','nieuwbouw','risico'],bron:''},
 {id:'hwx-180',thema:'hypotheek-nhg-woning',vraag:'Wat is een zelfbouwkavel en waar let je op?',antwoord:`Bij zelfbouw koopt de klant een kavel en laat hij zelf bouwen. Financiering verloopt vaak in fasen via een bouwdepot. De geldverstrekker vraagt een begroting, vergunning en aannemingsovereenkomst. Controleer de voorwaarden van de geldverstrekker.`,tags:['zelfbouw','kavel','bouwdepot'],bron:''},
 {id:'hwx-181',thema:'hypotheek-nhg-woning',vraag:'Hoe wordt de waarde bij zelfbouw bepaald?',antwoord:`De waarde is vaak de grondprijs plus de bouwkosten, bevestigd door een taxatie op basis van tekeningen en begroting. Na oplevering kan een nieuwe taxatie nodig zijn. Afwijkingen van het bouwplan kunnen de waarde raken. Leg tekeningen en begroting vast.`,tags:['zelfbouw','waarde','taxatie'],bron:''},
 {id:'hwx-182',thema:'hypotheek-nhg-woning',vraag:'Kan een bedrijfswoning als eigen woning worden gefinancierd?',antwoord:`Een bedrijfswoning hoort bij een bedrijf of bedrijventerrein. Bewoning door derden is vaak niet toegestaan of beperkt. Geldverstrekkers zijn hierom terughoudend. Controleer het omgevingsplan en de voorwaarden van de geldverstrekker.`,tags:['bedrijfswoning','bestemming','financiering'],bron:''},
 {id:'hwx-183',thema:'hypotheek-nhg-woning',vraag:'Hoe lang mag een nieuwbouwwoning leeg staan en toch als eigen woning gelden?',antwoord:`Een woning die nog niet wordt bewoond, kan onder voorwaarden tot 3 jaar als eigen woning gelden als de klant er wil gaan wonen. Dit geldt voor de periode na aankoop of tijdens de bouw. Na die termijn vervalt de status. Controleer de actuele regels bij de Belastingdienst.`,tags:['nieuwbouw','leegstand','eigen woning'],bron:'Belastingdienst'},
 {id:'hwx-184',thema:'hypotheek-nhg-woning',vraag:'Hoe financier je een verbouwing bij een bestaande hypotheek?',antwoord:`Dat kan met een verhoging bij de huidige geldverstrekker of een tweede hypotheek. De verhoging wordt opnieuw getoetst aan de normen en de waarde na verbouwing. De rente is alleen aftrekbaar als aan de voorwaarden wordt voldaan. Leg de specificatie en de fiscale toets vast.`,tags:['verbouwing','verhogen','bestaande hypotheek'],bron:''},
 {id:'hwx-185',thema:'hypotheek-nhg-woning',vraag:'Welke verbouwingen gelden fiscaal als verbetering van de eigen woning?',antwoord:`Verbetering is een uitbreiding of kwaliteitsverhoging van de woning. Gewoon onderhoud valt daar meestal niet onder. Het verschil is van belang voor de renteaftrek. Verwijs bij twijfel naar de Belastingdienst.`,tags:['verbouwing','verbetering','onderhoud'],bron:'Belastingdienst'},
 {id:'hwx-186',thema:'hypotheek-nhg-woning',vraag:'Is een nieuwe keuken financierbaar met de hypotheek?',antwoord:`Een nieuwe keuken kan als verbetering gelden als die kwalitatief beter is dan de oude. Een vervanging op gelijk niveau is eerder onderhoud. Dit is relevant voor de renteaftrek. Leg de onderbouwing vast en verwijs bij twijfel naar de Belastingdienst.`,tags:['keuken','verbetering','renteaftrek'],bron:'Belastingdienst'},
 {id:'hwx-187',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een kangoeroewoning?',antwoord:`In een kangoeroewoning wonen twee huishoudens in één woning met een eigen deel. De financiering hangt af van wie eigenaar is en wie er woont. Ook fiscaal en bij verzekeringen zijn er aandachtspunten. Leg de eigendom en afspraken vast en controleer de voorwaarden van de geldverstrekker.`,tags:['kangoeroewoning','meergeneratie','eigendom'],bron:''},
 {id:'hwx-188',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een verbouwing die de klant grotendeels zelf uitvoert?',antwoord:`Bij zelfwerkzaamheid worden vaak alleen materiaalkosten gefinancierd. De taxateur moet de waarde na verbouwing realistisch inschatten. Het risico op vertraging en kwaliteit is groter. Controleer de voorwaarden van de geldverstrekker.`,tags:['zelfwerkzaamheid','verbouwing','materiaal'],bron:''},
 {id:'hwx-189',thema:'hypotheek-nhg-woning',vraag:'Kan een uitbouw zonder vergunning toch worden gefinancierd?',antwoord:`Als de uitbouw vergunningsvrij is, is dat geen probleem. Als er een vergunning nodig is en die ontbreekt, kan de geldverstrekker voorwaarden stellen. Laat de klant de vergunningplicht nagaan via het omgevingsloket. Leg de uitkomst vast.`,tags:['uitbouw','vergunning','omgevingsloket'],bron:'Omgevingswet'},
 {id:'hwx-190',thema:'hypotheek-nhg-woning',vraag:'Hoe neem je de kosten van tijdelijke woonruimte tijdens een grote verbouwing mee?',antwoord:`Bij een grote verbouwing moet de klant soms tijdelijk elders wonen. Die kosten zijn in de regel niet met de hypotheek te financieren. Ze tellen wel mee in het budget. Bespreek de duur en de kosten en leg dat vast.`,tags:['verbouwing','tijdelijke woonruimte','budget'],bron:''},
 {id:'hwx-191',thema:'hypotheek-nhg-woning',vraag:'Hoe reken je het effect van een verbouwing op de LTV?',antwoord:`Deel de totale lening na verbouwing door de getaxeerde waarde na verbouwing. Rekenvoorbeeld: een lening van 330 bij een waarde na verbouwing van 300 geeft een LTV van 110%. Dat past dan niet binnen de reguliere grens. De klant moet dan eigen middelen inbrengen.`,tags:['ltv','verbouwing','rekenvoorbeeld'],bron:'Trhk'},
 {id:'hwx-192',thema:'hypotheek-nhg-woning',vraag:'Wat zijn veelgemaakte fouten bij een bouwdepot?',antwoord:`De opgegeven verbouwing sluit niet aan bij de taxatie. Facturen worden te laat ingediend en het depot verloopt. Onderhoud wordt als verbetering opgevoerd. Ook wordt de depotrente fiscaal vaak vergeten.`,tags:['bouwdepot','fouten','controle'],bron:''},
 {id:'hwx-193',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een woning met korting en terugkoopplicht van een corporatie?',antwoord:`Bij zo een koopconstructie koopt de klant met korting en geldt een terugkoopplicht of waardedeling. De waardeontwikkeling wordt dan gedeeld met de corporatie. Geldverstrekkers stellen specifieke voorwaarden. Lees de regeling goed en leg de gevolgen vast.`,tags:['koopconstructie','corporatie','waardedeling'],bron:''},
 {id:'hwx-194',thema:'hypotheek-nhg-woning',vraag:'Wat is een bouwdepot bij nieuwbouw in termijnen?',antwoord:`De aannemer stuurt per bouwfase een termijnfactuur. De klant geeft akkoord en de geldverstrekker betaalt uit het depot. Controleer of de termijnen overeenkomen met het contract. Leg goedgekeurde termijnen vast.`,tags:['bouwdepot','termijnen','nieuwbouw'],bron:''},
 {id:'hwx-195',thema:'hypotheek-nhg-woning',vraag:'Hoe controleer je bij nieuwbouw of de aannemer de juiste termijn factureert?',antwoord:`Vergelijk de termijnfactuur met het termijnschema in de aannemingsovereenkomst. Een termijn mag pas worden betaald als de fase is bereikt. Bij twijfel kan de klant een bouwkundige laten controleren. Adviseer de klant hier zorgvuldig mee om te gaan.`,tags:['termijnfactuur','aannemer','controle'],bron:''},
 {id:'hwx-196',thema:'hypotheek-nhg-woning',vraag:'Wat betekent een opleveringskeuring bij nieuwbouw?',antwoord:`Bij oplevering inspecteert de koper de woning op gebreken, vaak met een deskundige. Gebreken worden op een proces-verbaal gezet. De aannemer moet ze binnen een termijn herstellen. Er kan een deel van de koopsom worden ingehouden volgens de regeling.`,tags:['oplevering','keuring','nieuwbouw'],bron:''},
 {id:'hwx-197',thema:'hypotheek-nhg-woning',vraag:'Wat is de vijf procent-regeling bij nieuwbouw?',antwoord:`Volgens het Burgerlijk Wetboek kan de koper een deel van de aanneemsom bij de notaris in depot laten tot gebreken zijn hersteld. Dit geeft zekerheid voor herstel na oplevering. De regeling geldt alleen als de wettelijke voorwaarden zijn vervuld. Controleer de details bij de notaris.`,tags:['nieuwbouw','depot notaris','gebreken'],bron:'BW'},
 {id:'hwx-198',thema:'hypotheek-nhg-woning',vraag:'Wat is de Wet kwaliteitsborging voor het bouwen?',antwoord:`Deze wet regelt een andere manier van toezicht op bouwkwaliteit, met een kwaliteitsborger. Ook is de aansprakelijkheid van aannemers voor gebreken uitgebreid. De wet wordt gefaseerd ingevoerd voor bepaalde bouwwerken. Verwijs voor details naar de rijksoverheid.`,tags:['wkb','bouwkwaliteit','aansprakelijkheid'],bron:'Wkb'},
 {id:'hwx-199',thema:'hypotheek-nhg-woning',vraag:'Wat gebeurt er met de financiering als de aannemer failliet gaat?',antwoord:`Een garantieregeling kan dan bijdragen aan afbouw of vergoeding van schade. De voorwaarden verschillen per regeling. Er kan vertraging en extra kosten ontstaan. Bespreek dit risico met de klant en controleer de garantie.`,tags:['faillissement','aannemer','garantie'],bron:''},
 {id:'hwx-200',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een nieuwbouwproject dat ernstige vertraging oploopt?',antwoord:`Vertraging verlengt de dubbele lasten en kan de offerte of het depot laten verlopen. Vraag tijdig verlenging aan bij de geldverstrekker. Herbereken de lasten met de nieuwe planning. Leg de afspraken en de gevolgen voor de klant vast.`,tags:['nieuwbouw','vertraging','dubbele lasten'],bron:''},
 {id:'hwx-201',thema:'hypotheek-nhg-woning',vraag:'Rekenvoorbeeld: hoeveel labelruimte bij aankoop heeft een woning met label A+++?',antwoord:`Voor 2026 geeft label A+++ bij aankoop €25.000 extra leenruimte. Een woning met label A++++ geeft €30.000, of €40.000 met energieprestatiegarantie. Voor verduurzaming is er bij A+++ geen extra ruimte. Leg het label en de berekening vast.`,tags:['label a+++','rekenvoorbeeld','leenruimte'],bron:'Trhk'},
 {id:'hwx-202',thema:'hypotheek-nhg-woning',vraag:'Welke offertes vraag je op voor een verduurzamingsdepot?',antwoord:`Vraag per maatregel een offerte met omschrijving, kosten en uitvoerder. Zo is aantoonbaar dat het geld aan energiebesparende maatregelen wordt besteed. Geldverstrekkers vragen dit vaak voor uitbetaling. Leg de offertes vast in het dossier.`,tags:['verduurzaming','offertes','bouwdepot'],bron:''},
 {id:'hwx-203',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met verduurzaming van een monument?',antwoord:`Bij een monument zijn veel maatregelen vergunningplichtig of beperkt. Denk aan isolatie aan de buitenzijde of zonnepanelen. Dit beperkt wat met het verduurzamingsdepot kan. Laat de klant de mogelijkheden bij de gemeente nagaan.`,tags:['monument','verduurzaming','vergunning'],bron:''},
 {id:'hwx-204',thema:'hypotheek-nhg-woning',vraag:'Welke bouwkundige risicos kan na-isolatie geven?',antwoord:`Na-isolatie kan vocht- en ventilatieproblemen geven als het niet goed wordt uitgevoerd. Bij oudere woningen speelt dit sterker. Een deskundige kan beoordelen of de constructie geschikt is. Adviseer de klant hierover en leg dat vast.`,tags:['isolatie','vocht','ventilatie'],bron:''},
 {id:'hwx-205',thema:'hypotheek-nhg-woning',vraag:'Valt een thuisbatterij onder de energiebesparende voorzieningen?',antwoord:`Dat hangt af van de actuele lijst bij de regeling. Niet elke duurzame investering geldt als energiebesparende voorziening. Controleer de lijst en de voorwaarden van de geldverstrekker. Leg de beoordeling vast.`,tags:['thuisbatterij','energiebesparende voorziening','lijst'],bron:'Trhk'},
 {id:'hwx-206',thema:'hypotheek-nhg-woning',vraag:'Wat als de verduurzamingsmaatregelen goedkoper uitvallen dan begroot?',antwoord:`Het niet bestede deel blijft in het depot. Na afloop wordt het meestal afgelost op de lening. De klant kan soms extra maatregelen toevoegen als die aan de voorwaarden voldoen. Controleer de voorwaarden van de geldverstrekker.`,tags:['verduurzaming','depot','restant'],bron:''},
 {id:'hwx-207',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een klant die verduurzaming wil uitstellen tot na de verhuizing?',antwoord:`De verduurzamingsruimte bij aankoop is gekoppeld aan het depot en de looptijd ervan. Bij uitstel kan financiering later via een verhoging, met een nieuwe toets. De voorwaarden kunnen dan anders zijn. Bespreek de voor- en nadelen en leg de keuze vast.`,tags:['verduurzaming','uitstel','verhoging'],bron:''},
 {id:'hwx-208',thema:'hypotheek-nhg-woning',vraag:'Waarom is een woning met label A+++ niet geschikt voor extra verduurzamingsruimte?',antwoord:`Voor woningen met label A+++ of beter is voor 2026 geen extra verduurzamingsruimte. Het idee is dat het besparingspotentieel dan beperkt is. De labelruimte bij aankoop is voor zo een woning wel hoger. Reken beide posten apart door.`,tags:['energielabel','verduurzaming','a+++'],bron:'Trhk'},
 {id:'hwx-209',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij aankoop van een voormalige huurwoning van een corporatie?',antwoord:`Zo een woning ligt vaak in een complex waar de corporatie nog woningen bezit. Er kunnen een anti-speculatiebeding en een zelfbewoningsplicht gelden. Ook de VvE en het onderhoudsniveau zijn aandachtspunten. Lees de koopakte en de VvE-stukken.`,tags:['corporatie','voormalige huurwoning','vve'],bron:''},
 {id:'hwx-210',thema:'hypotheek-nhg-woning',vraag:'Waar let je op bij een appartement in een complex met een corporatie als grootste eigenaar?',antwoord:`De corporatie heeft dan vaak een groot deel van de stemmen in de VvE. Besluiten over onderhoud en verduurzaming worden daardoor sterk door haar bepaald. Dat kan gunstig of ongunstig zijn voor de klant. Bespreek dit en lees de notulen.`,tags:['vve','corporatie','stemrecht'],bron:''},
 {id:'hwx-211',thema:'hypotheek-nhg-woning',vraag:'Wat is een maatwerkadvies voor verduurzaming?',antwoord:`Een energieadviseur beoordeelt de woning en adviseert welke maatregelen zinvol zijn. Het advies geeft een indicatie van kosten en besparing. Het kan de onderbouwing van het bouwdepot versterken. Het is geen voorwaarde in de Trhk, maar wel nuttig.`,tags:['maatwerkadvies','energieadvies','maatregelen'],bron:''},
 {id:'hwx-212',thema:'hypotheek-nhg-woning',vraag:'Welke fouten komen vaak voor bij financiering van verduurzaming?',antwoord:`Het label is verlopen of verkeerd overgenomen. Maatregelen in het depot zijn geen energiebesparende voorziening. Ook wordt vergeten dat de klant de extra lasten moet kunnen dragen. Controleer de lijst van toegestane maatregelen en leg de besteding vast.`,tags:['verduurzaming','fouten','controle'],bron:''},
 {id:'hwx-213',thema:'hypotheek-nhg-woning',vraag:'Moet de klant de extra lasten van verduurzaming kunnen dragen?',antwoord:`De verduurzamingsruimte is een uitzondering op de inkomenstoets. Toch blijft de zorgplicht van de adviseur gelden. Bespreek of de besparing de extra lasten dekt en wat het risico is als dat tegenvalt. Leg die afweging vast in het dossier.`,tags:['verduurzaming','zorgplicht','lasten'],bron:'Wft'},
 {id:'hwx-214',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met zonnepanelen die worden geleased of gehuurd?',antwoord:`Geleasde panelen zijn geen eigendom van de klant. Er kan een opstalrecht of contract op rusten dat de verkoop of financiering raakt. De maandlast telt mogelijk mee als verplichting. Controleer het contract en de voorwaarden van de geldverstrekker.`,tags:['zonnepanelen','lease','opstalrecht'],bron:''},
 {id:'hwx-215',thema:'hypotheek-nhg-woning',vraag:'Telt een warmtepomp mee als energiebesparende voorziening?',antwoord:`Een warmtepomp valt in de regel onder de energiebesparende voorzieningen. De lijst van maatregelen staat in de bijlage bij de regeling. Controleer de actuele lijst. Leg de offerte en de soort maatregel vast.`,tags:['warmtepomp','energiebesparende voorziening','maatregel'],bron:'Trhk'},
 {id:'hwx-216',thema:'hypotheek-nhg-woning',vraag:'Kan de klant subsidie krijgen naast de hypotheek voor verduurzaming?',antwoord:`Er bestaan landelijke en gemeentelijke subsidies voor verduurzaming. Voorwaarden en budgetten wijzigen regelmatig. Subsidie kan de benodigde lening verlagen. Verwijs naar de actuele regelingen van RVO en de gemeente.`,tags:['subsidie','verduurzaming','rvo'],bron:'RVO'},
 {id:'hwx-217',thema:'hypotheek-nhg-woning',vraag:'Wat is het Warmtefonds?',antwoord:`Het Warmtefonds biedt leningen voor verduurzaming van woningen, ook voor VvE’s. De voorwaarden en de rente wijzigen periodiek. Het is een alternatief of aanvulling op financiering via de hypotheek. Verwijs naar het fonds voor de actuele voorwaarden.`,tags:['warmtefonds','lening','verduurzaming'],bron:'Nationaal Warmtefonds'},
 {id:'hwx-218',thema:'hypotheek-nhg-woning',vraag:'Telt een lening van het Warmtefonds mee in de hypotheektoets?',antwoord:`Een bestaande lening telt in de regel mee als financiële verplichting. Hoe dat precies gebeurt, hangt af van de leningsvorm en de geldverstrekker. Vraag de leningsgegevens op. Controleer de voorwaarden van de geldverstrekker.`,tags:['warmtefonds','toetsing','verplichting'],bron:''},
 {id:'hwx-219',thema:'hypotheek-nhg-woning',vraag:'Kan een VvE eisen stellen aan verduurzaming door individuele eigenaren?',antwoord:`Maatregelen aan gemeenschappelijke delen of het uiterlijk vragen vaak toestemming van de VvE. Het reglement en de splitsingsakte bepalen wat is toegestaan. Zonder toestemming kan de VvE herstel eisen. Laat de klant dit vooraf nagaan.`,tags:['vve','toestemming','verduurzaming'],bron:''},
 {id:'hwx-220',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen een energielabel en een energie-index?',antwoord:`Het energielabel geeft een klasse aan de woning, op basis van een berekening. Een energie-index is een oudere methode. Voor de leennormen telt het geregistreerde energielabel. Controleer het label in het openbare register.`,tags:['energielabel','energie-index','register'],bron:'RVO'},
 {id:'hwx-221',thema:'hypotheek-nhg-woning',vraag:'Waar controleer je het geregistreerde energielabel van een woning?',antwoord:`Het label staat in een openbaar register van de overheid. Je kunt zoeken op adres. Controleer de geldigheidsdatum en de labelklasse. Leg een kopie vast in het dossier.`,tags:['energielabel','register','controle'],bron:'RVO'},
 {id:'hwx-222',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een energielabel dat niet klopt met de werkelijke staat?',antwoord:`Een label kan verouderd zijn of op foutieve gegevens berusten. Voor de leennormen geldt het geregistreerde label. Een nieuw label laten maken kan de werkelijke staat beter weergeven. Bespreek dit met de klant.`,tags:['energielabel','afwijking','nieuw label'],bron:''},
 {id:'hwx-223',thema:'hypotheek-nhg-woning',vraag:'Wat is het verschil tussen servicekosten en de VvE-bijdrage?',antwoord:`De VvE-bijdrage dekt onderhoud en reserveringen voor het gebouw. Servicekosten kunnen ook kosten van diensten bevatten, zoals schoonmaak of een conciërge. In de praktijk worden de begrippen door elkaar gebruikt. Vraag een specificatie op.`,tags:['vve-bijdrage','servicekosten','verschil'],bron:''},
 {id:'hwx-224',thema:'hypotheek-nhg-woning',vraag:'Wat is een meerjarenonderhoudsplan?',antwoord:`Een meerjarenonderhoudsplan geeft het verwachte onderhoud aan het gebouw voor een reeks jaren. Op basis daarvan bepaalt de VvE de reservering. Het plan helpt in te schatten of extra bijdragen nodig zijn. Vraag het op en bespreek het met de klant.`,tags:['mjop','onderhoud','vve'],bron:'BW'},
 {id:'hwx-225',thema:'hypotheek-nhg-woning',vraag:'Wat is het risico van een VvE met te lage reserves?',antwoord:`Bij onvoldoende reserves kan de VvE extra bijdragen van eigenaren vragen. Dat kan onverwachte lasten geven voor de klant. Het kan ook de verkoopbaarheid raken. Bespreek dit en leg het vast.`,tags:['vve','reserves','extra bijdrage'],bron:''},
 {id:'hwx-226',thema:'hypotheek-nhg-woning',vraag:'Hoe controleer je of een VvE actief is?',antwoord:`Vraag de notulen van de laatste vergaderingen, de jaarrekening en de begroting op. Controleer of er een inschrijving bij de Kamer van Koophandel is. Een actieve VvE heeft een bestuur en een rekening. Leg de stukken vast.`,tags:['vve','actief','documenten'],bron:'KVK'},
 {id:'hwx-227',thema:'hypotheek-nhg-woning',vraag:'Wat is een slapende VvE en wat zijn de gevolgen?',antwoord:`Een slapende VvE vergadert niet en reserveert niet voor onderhoud. Groot onderhoud wordt dan uitgesteld. Geldverstrekkers kunnen dit als risico zien. Bespreek de gevolgen voor onderhoud en kosten.`,tags:['slapende vve','onderhoud','risico'],bron:''},
 {id:'hwx-228',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een VvE-besluit over groot onderhoud kort na aankoop?',antwoord:`Een besluit kan leiden tot een extra bijdrage. Vraag de notulen op om te zien wat er is besloten. De koopovereenkomst bepaalt wie de kosten draagt van besluiten voor levering. Bespreek de verdeling met de klant.`,tags:['vve','besluit','onderhoud'],bron:''},
 {id:'hwx-229',thema:'hypotheek-nhg-woning',vraag:'Wat is de informatieplicht van de VvE bij verkoop van een appartement?',antwoord:`De verkoper moet de koper relevante informatie geven over de VvE. De notaris vraagt vaak een verklaring van de VvE op over achterstanden en bijdragen. Achterstanden van de verkoper kunnen gevolgen hebben voor de koper. Controleer dit voor levering.`,tags:['vve','informatie','notaris'],bron:'BW'},
 {id:'hwx-230',thema:'hypotheek-nhg-woning',vraag:'Kan een koper aansprakelijk worden voor achterstanden van de verkoper bij de VvE?',antwoord:`De koper kan onder voorwaarden naast de verkoper aansprakelijk zijn voor bijdragen van het lopende en vorige boekjaar. De notaris vraagt daarom een verklaring van de VvE op. Bij een ontbrekende verklaring is dat risico groter. Laat de notaris dit regelen.`,tags:['vve','achterstanden','aansprakelijkheid'],bron:'BW'},
 {id:'hwx-231',thema:'hypotheek-nhg-woning',vraag:'Hoe weeg je de servicekosten mee bij de betaalbaarheid?',antwoord:`De servicekosten zijn een vaste last voor de klant. Ze tellen niet altijd mee in de wettelijke toets, maar wel in de betaalbaarheid. Neem ze mee in het budgetgesprek. Leg vast hoe je ze hebt besproken.`,tags:['servicekosten','betaalbaarheid','vve'],bron:''},
 {id:'hwx-232',thema:'hypotheek-nhg-woning',vraag:'Kan een VvE zelf een lening afsluiten voor verduurzaming?',antwoord:`Ja, een VvE kan een collectieve lening afsluiten, bijvoorbeeld bij een fonds of bank. De aflossing loopt dan via de bijdragen van de eigenaren. Dit verhoogt de maandlasten van de klant. Vraag naar zulke leningen bij aankoop.`,tags:['vve','lening','verduurzaming'],bron:''},
 {id:'hwx-233',thema:'hypotheek-nhg-woning',vraag:'Is een VvE-lening zichtbaar als verplichting bij de hypotheekaanvraag?',antwoord:`Een collectieve VvE-lening staat niet op naam van de klant. Ze verhoogt wel de VvE-bijdrage. Geldverstrekkers kijken soms naar de hoogte van de bijdrage. Controleer de voorwaarden van de geldverstrekker.`,tags:['vve','lening','toetsing'],bron:''},
 {id:'hwx-234',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een appartement in een groot complex met een hoofd-VvE en onder-VvE?',antwoord:`Soms is er een hoofd-VvE en zijn er onderliggende VvE’s. Kosten en besluiten kunnen op meerdere niveaus liggen. Vraag stukken van alle betrokken VvE’s op. Leg de structuur vast.`,tags:['vve','hoofd-vve','complex'],bron:''},
 {id:'hwx-235',thema:'hypotheek-nhg-woning',vraag:'Wat is een splitsingsakte en waarom lees je die?',antwoord:`De splitsingsakte beschrijft de appartementsrechten en de breukdelen. Het reglement regelt rechten en plichten van eigenaren. Bijzondere bepalingen, zoals verhuurbeperkingen, staan daarin. Lees de akte voor het advies.`,tags:['splitsingsakte','reglement','appartement'],bron:''},
 {id:'hwx-236',thema:'hypotheek-nhg-woning',vraag:'Wat is een breukdeel in een VvE?',antwoord:`Het breukdeel bepaalt het aandeel van een eigenaar in het gebouw en vaak in de kosten. Het kan ook het stemrecht bepalen. Een groter breukdeel betekent vaak hogere bijdragen. Controleer de splitsingsakte.`,tags:['breukdeel','vve','kosten'],bron:''},
 {id:'hwx-237',thema:'hypotheek-nhg-woning',vraag:'Wat zijn veelgemaakte fouten bij het VvE-onderzoek?',antwoord:`Notulen worden niet gelezen, terwijl daar besluiten over onderhoud staan. Het meerjarenonderhoudsplan wordt niet opgevraagd. Ook wordt de reservepositie niet vergeleken met het plan. Een vaste checklist voorkomt dit.`,tags:['vve','fouten','checklist'],bron:''},
 {id:'hwx-238',thema:'hypotheek-nhg-woning',vraag:'Hoe neem je een verduurzamingsplan van de VvE mee in het advies?',antwoord:`Een plan kan leiden tot een hogere bijdrage of een collectieve lening. Het kan ook de energielasten verlagen en de waarde beïnvloeden. Vraag het plan en de financiering ervan op. Bespreek de gevolgen voor de woonlasten.`,tags:['vve','verduurzamingsplan','woonlasten'],bron:''},
 {id:'hwx-239',thema:'hypotheek-nhg-woning',vraag:'Rekenvoorbeeld: hoeveel extra ruimte heeft een woning met label C bij aankoop en verduurzaming?',antwoord:`Bij aankoop is de labelruimte voor 2026 €5.000. Voor verduurzaming is de ruimte €15.000. Of beide volledig worden benut, hangt af van de geldverstrekker en de maatregelen. Leg beide bedragen apart vast.`,tags:['label c','rekenvoorbeeld','leenruimte'],bron:'Trhk'},
 {id:'hwx-240',thema:'hypotheek-nhg-woning',vraag:'Hoe verwerk je verduurzaming bij een alleenstaande klant?',antwoord:`Voor alleenstaanden telt de leennorm voor 2026 een vast bedrag van €17.000 extra mee bij het toetsinkomen. De verduurzamingsruimte staat daar los van. Reken beide elementen apart uit. Leg de berekening vast.`,tags:['alleenstaande','verduurzaming','leennormen'],bron:'Trhk'},
 {id:'hwx-241',thema:'hypotheek-nhg-woning',vraag:'Wat is het effect van verduurzaming op de taxatiewaarde?',antwoord:`Verduurzaming kan de marktwaarde verhogen, maar niet altijd met het geïnvesteerde bedrag. De taxateur kijkt wat de markt ervoor betaalt. Een beter label kan de verkoopbaarheid wel verbeteren. Bespreek dit met de klant zonder waardestijging te beloven.`,tags:['verduurzaming','taxatiewaarde','marktwaarde'],bron:''},
 {id:'hwx-242',thema:'hypotheek-nhg-woning',vraag:'Wat is een nul-op-de-meter-woning en hoe wordt die gefinancierd?',antwoord:`Een nul-op-de-meter-woning wekt over een jaar zoveel energie op als ze gebruikt. Vaak hoort daar een energieprestatiegarantie bij. Dit kan extra leenruimte geven als aan de eisen is voldaan. Controleer het label en de garantie.`,tags:['nul-op-de-meter','energieprestatiegarantie','leenruimte'],bron:'Trhk'},
 {id:'hwx-243',thema:'hypotheek-nhg-woning',vraag:'Kan verduurzaming bij een appartement individueel worden gefinancierd?',antwoord:`Maatregelen aan de eigen woning, zoals binnenisolatie, kunnen individueel. Maatregelen aan gemeenschappelijke delen, zoals dak of gevel, beslist de VvE. Dan loopt financiering vaak via de VvE. Bespreek wat de klant zelf kan doen.`,tags:['appartement','verduurzaming','vve'],bron:''},
 {id:'hwx-244',thema:'hypotheek-nhg-woning',vraag:'Mag een appartementseigenaar zonnepanelen op het gezamenlijke dak plaatsen?',antwoord:`Het dak is meestal gemeenschappelijk eigendom van de VvE. Plaatsing vraagt dan toestemming van de VvE. Het reglement kan dit regelen. Verwijs de klant naar de VvE.`,tags:['zonnepanelen','vve','dak'],bron:''},
 {id:'hwx-245',thema:'hypotheek-nhg-woning',vraag:'Hoe leg je de verduurzamingsadvisering vast in het dossier?',antwoord:`Leg het label, de maatregelen, de offertes en de berekening van de leenruimte vast. Noteer de besproken besparing en lasten. Vermeld ook subsidies of fondsen die zijn bekeken. Zo is het advies te reconstrueren.`,tags:['verduurzaming','vastlegging','dossier'],bron:''},
 {id:'hwx-246',thema:'hypotheek-nhg-woning',vraag:'Wat als de klant de verduurzamingsmaatregelen niet binnen de depottermijn uitvoert?',antwoord:`Het restant wordt dan vaak afgelost op de lening. Soms is verlenging mogelijk. De extra leenruimte vervalt daarmee in de praktijk. Controleer de voorwaarden van de geldverstrekker.`,tags:['verduurzaming','depottermijn','restant'],bron:''},
 {id:'hwx-247',thema:'hypotheek-nhg-woning',vraag:'Is isolatie altijd een energiebesparende voorziening?',antwoord:`Isolatie van dak, vloer, gevel en glas valt in de regel onder de lijst van voorzieningen. Controleer de actuele lijst bij de regeling. Gewoon onderhoud zonder energiebesparing valt er niet onder. Leg de soort maatregel vast.`,tags:['isolatie','energiebesparende voorziening','lijst'],bron:'Trhk'},
 {id:'hwx-248',thema:'hypotheek-nhg-woning',vraag:'Hoe weeg je de terugverdientijd van verduurzaming mee in het advies?',antwoord:`De terugverdientijd hangt af van investering, besparing en energieprijzen. Die zijn onzeker en veranderen. Gebruik een realistische bandbreedte. Leg vast dat de klant de onzekerheid begrijpt.`,tags:['terugverdientijd','verduurzaming','afweging'],bron:''},
 {id:'hwx-249',thema:'hypotheek-nhg-woning',vraag:'Kan een woning met erfpacht en VvE gecombineerd verduurzaamd worden via de hypotheek?',antwoord:`Ja, dat kan in principe binnen de normen. Erfpacht en VvE-regels kunnen beperkingen geven. Controleer de erfpachtvoorwaarden en het VvE-reglement. Leg de afstemming vast.`,tags:['erfpacht','vve','verduurzaming'],bron:''},
 {id:'hwx-250',thema:'hypotheek-nhg-woning',vraag:'Hoe ga je om met een klant die een EBV wil financieren na de aankoop?',antwoord:`Bij een latere verhoging gelden de dan actuele leennormen en het dan geldende label. De verduurzamingsruimte kan dan worden gebruikt als aan de voorwaarden is voldaan. Er is mogelijk een nieuwe taxatie nodig. Controleer de voorwaarden van de geldverstrekker.`,tags:['ebv','verhoging','na aankoop'],bron:'Trhk'}
]);
